const CLEARED_TABLE_KEYS = {
  inv: "srt_cleared_inv_v1",
  pay: "srt_cleared_pay_v1",
  cp: "srt_cleared_cp_v1",
  rp: "srt_cleared_rp_v1",
  exp: "srt_cleared_exp_v1",
  fr: "srt_cleared_fr_v1",
  trader: "srt_cleared_trader_v1",
  vehicle: "srt_cleared_vehicle_v1",
};
function isTableCleared(sheet) {
  try {
    return localStorage.getItem(CLEARED_TABLE_KEYS[sheet]) === "1";
  } catch (e) {
    return false;
  }
}
function markTableCleared(sheet) {
  try {
    localStorage.setItem(CLEARED_TABLE_KEYS[sheet], "1");
  } catch (e) {}
}
function clearTableClearedMarker(sheet) {
  try {
    localStorage.removeItem(CLEARED_TABLE_KEYS[sheet]);
  } catch (e) {}
}
Object.keys(CLEARED_TABLE_KEYS).forEach((sheet) => {
  if (isTableCleared(sheet)) STATE[sheet] = [];
});

window.srtSyncEmptyServerTables = async function () {
  if (typeof SrtApi === "undefined") return;
  const endpoints = {
    inv: "/api/invoices",
    pay: "/api/payments",
    cp: "/api/company-payments",
    rp: "/api/received-payments",
    exp: "/api/expenses",
    fr: "/api/freight-rates",
    trader: "/api/traders",
    vehicle: "/api/vehicles",
  };
  await Promise.all(
    Object.entries(endpoints).map(async ([sheet, endpoint]) => {
      try {
        const rows = await SrtApi.get(`${endpoint}?limit=500`);
        if (Array.isArray(rows) && rows.length === 0) {
          STATE[sheet] = [];
          markTableCleared(sheet);
        }
      } catch (e) {
        // Local demo data remains available when a module is not accessible.
      }
    }),
  );
  renderAll(null);
};
try {
  STATE.trader = JSON.parse(
    localStorage.getItem("srt_trader_details_v1") || "[]",
  );
  if (!Array.isArray(STATE.trader)) STATE.trader = [];
} catch (e) {
  STATE.trader = [];
}
try {
  STATE.vehicle = JSON.parse(
    localStorage.getItem("srt_vehicle_details_v1") || "[]",
  );
  if (!Array.isArray(STATE.vehicle)) STATE.vehicle = [];
} catch (e) {
  STATE.vehicle = [];
}
STATE.trader.forEach((r, i) => (r["Sr. No."] = String(i + 1)));
STATE.vehicle.forEach((r, i) => (r["Sr. No."] = String(i + 1)));
Object.keys(CLEARED_TABLE_KEYS).forEach((sheet) => {
  if (isTableCleared(sheet)) STATE[sheet] = [];
});
(STATE.rp || []).forEach((r, i) => {
  r["Sr. No."] = String(i + 1);
  if (
    r["Received Date"] === undefined ||
    r["Received Date"] === null ||
    String(r["Received Date"]).trim() === ""
  )
    r["Received Date"] = "-";
  const a = parseFloat(r["Invoice Amount"]),
    b = parseFloat(r["Received Amount"]);
  r["Remaining Amount"] =
    !isNaN(a) && !isNaN(b)
      ? String(Math.round((a - b) * 100) / 100)
      : r["Remaining Amount"] || "-";
});
