// ── UTILS ──
function inr(v) {
  const n = parseFloat(v);
  if (isNaN(n) || v === "-") return "-";
  if (n === 0) return "₹0";
  if (n >= 10000000) return "₹" + (n / 10000000).toFixed(2) + "Cr";
  if (n >= 100000) return "₹" + (n / 100000).toFixed(1) + "L";
  if (n >= 1000) return "₹" + n.toLocaleString("en-IN");
  return "₹" + n;
}
function sc(v) {
  const lv = (v || "").toLowerCase().trim();
  if (
    lv.includes("complete") ||
    lv.includes("received") ||
    lv.includes("confirm") ||
    lv.includes("done") ||
    lv.includes("submit")
  )
    return "bg";
  if (lv.includes("pending")) return "by";
  if (lv.includes("created")) return "bc";
  if (lv.includes("advance")) return "bo";
  if (lv.includes("cancel") || lv.includes("reject")) return "br";
  return "bx";
}
function badge(v) {
  return v && v !== "-" ? `<span class="badge ${sc(v)}">${v}</span>` : "-";
}
function sv(v) {
  const s = String(v ?? "").trim();
  return s === "" || s === "nan" || s === "NaT" || s === "None" ? "-" : s;
}
function isLink(v) {
  return (
    v && v !== "-" && (v.startsWith("http://") || v.startsWith("https://"))
  );
}

let toastT;
function toast(m, c) {
  const t = document.getElementById("toastEl");
  t.textContent = m;
  t.style.borderLeftColor = c || "var(--orange)";
  t.classList.add("show");
  clearTimeout(toastT);
  toastT = setTimeout(() => t.classList.remove("show"), 3200);
}

// Sign-in controls are handled by srt-interactive-login-script below.

// ── NAV ──
function _navOriginal(el) {
  document.querySelectorAll(".ni").forEach((n) => n.classList.remove("active"));
  el.classList.add("active");
  document.querySelectorAll(".cp").forEach((p) => p.classList.remove("active"));
  document.getElementById("cp-" + el.dataset.pg)?.classList.add("active");
  if (el.dataset.pg === "att") {
    if (typeof initAtt === "function") initAtt();
  }
  if (el.dataset.pg === "gps") {
    if (typeof initGPS === "function") initGPS();
  }
}
function navById(id) {
  document.querySelectorAll(".cp").forEach((p) => p.classList.remove("active"));
  document.getElementById(id)?.classList.add("active");
  const pg = id.replace("cp-", "");
  document.querySelectorAll(".ni").forEach((n) => {
    if (n.dataset?.pg === pg) {
      document
        .querySelectorAll(".ni")
        .forEach((m) => m.classList.remove("active"));
      n.classList.add("active");
    }
  });
}

// ── RENDER TABLE (all columns from COLS) ──
function visRows(sheet) {
  let rows = STATE[sheet];
  const q = (filterQ[sheet] || "").toLowerCase();
  const col = filterCol[sheet] || {};
  if (q)
    rows = rows.filter((r) =>
      Object.values(r).some((v) => String(v).toLowerCase().includes(q)),
    );
  Object.entries(col).forEach(([k, v]) => {
    if (v)
      rows = rows.filter((r) =>
        String(r[k] || "")
          .toLowerCase()
          .includes(v.toLowerCase()),
      );
  });
  return rows;
}

function renderTable(sheet) {
  const matched = visRows(sheet).slice().reverse(); // newest / last-added record first
  const cols = COLS[sheet],
    allRows = STATE[sheet];
  const t = document.getElementById("t-" + sheet);
  if (!t) return;
  const totalPages = Math.max(1, Math.ceil(matched.length / TABLE_PAGE_SIZE));
  TABLE_PAGE[sheet] = Math.min(Math.max(TABLE_PAGE[sheet] || 1, 1), totalPages);
  const page = TABLE_PAGE[sheet];
  const startRow = (page - 1) * TABLE_PAGE_SIZE;
  const rows = matched.slice(startRow, startRow + TABLE_PAGE_SIZE);
  // Header
  const ths =
    '<th style="width:78px;text-align:center;position:sticky;left:0;z-index:3;background:#0a1826">Actions</th>' +
    cols.map((c) => `<th>${c.l}</th>`).join("");
  // Rows
  const trs =
    rows
      .map((r) => {
        const ri = allRows.indexOf(r);
        const isNew = ri === newRowIdx && sheet === modalSheet;
        const tds = cols
          .map((c) => {
            const raw = r[c.k];
            let v = sv(raw);
            if (c.image) {
              const hasImage =
                typeof raw === "string" && raw.startsWith("data:image/");
              v = hasImage
                ? `<a class="srt-rc-view" href="${raw}" target="_blank" title="View RC Image">🖼️ View</a>`
                : '<span style="opacity:.32">—</span>';
            } else if (c.link) {
              v = isLink(v)
                ? `<a class="link-btn" href="${v}" target="_blank">🔗 View</a>`
                : '<span style="opacity:.28">—</span>';
            } else if (c.badge) {
              v = badge(v);
            } else if (c.inr) {
              v = inr(v);
            } else if (c.mono) {
              v = `<span class="mono">${v}</span>`;
            }
            const cellTitle = c.image
              ? typeof raw === "string" && raw.startsWith("data:image/")
                ? "RC image uploaded"
                : "No RC image"
              : sv(raw);
            return `<td title="${cellTitle}">${v}</td>`;
          })
          .join("");
        const actStyle = "position:sticky;left:0;background:#0e1e2e;z-index:1;";
        const delBtn = isUserAdmin()
          ? `<button class="act-btn act-del icon-only" title="Delete" aria-label="Delete" onclick='askDelete("${sheet}",${ri})'>🗑️</button>`
          : `<button class="act-btn act-del icon-only" title="Delete (Admin only)" disabled style="opacity:0.5;cursor:not-allowed">🗑️</button>`;
        return `<tr class="${isNew ? "new-row" : ""}" onmouseenter="this.querySelectorAll('td[style*=background]').forEach(td=>td.style.background='#162535')" onmouseleave="this.querySelectorAll('td[style*=background]').forEach(td=>td.style.background='')">
      <td style="${actStyle}"><div class="row-acts"><button class="act-btn act-edit icon-only" title="Edit" aria-label="Edit" onclick='askEdit("${sheet}",${ri})'>✏️</button>${delBtn}</div></td>
      ${tds}
    </tr>`;
      })
      .join("") ||
    `<tr><td class="no-rows" colspan="${cols.length + 1}">No records found.</td></tr>`;
  t.innerHTML = `<thead><tr>${ths}</tr></thead><tbody>${trs}</tbody>`;
  // Update counts
  const cnt = document.getElementById("cnt-" + sheet);
  if (cnt) {
    if (!matched.length) cnt.textContent = `0 / ${allRows.length} records`;
    else {
      const from = startRow + 1,
        to = Math.min(startRow + rows.length, matched.length);
      cnt.textContent =
        matched.length === allRows.length
          ? `${from}-${to} of ${allRows.length} records`
          : `${from}-${to} of ${matched.length} filtered · ${allRows.length} total`;
    }
  }
  const nb = document.getElementById("nb-" + sheet);
  if (nb) nb.textContent = allRows.length;
  const sub = document.getElementById(sheet + "-sub");
  if (sub) {
    const colCount =
      {
        inv: 16,
        pay: 30,
        cp: 14,
        rp: 13,
        gps: 5,
        exp: 4,
        trader: 11,
        vehicle: 15,
      }[sheet] || cols.length;
    sub.textContent = `${allRows.length} records · ${colCount} columns`;
  }
  const pager = document.getElementById("pager-" + sheet);
  if (pager) {
    pager.innerHTML = `<button type="button" onclick="changeTablePage('${sheet}',-1)" ${page <= 1 ? "disabled" : ""}>← Previous</button><span class="page-info">Page ${page} of ${totalPages}</span><button type="button" onclick="changeTablePage('${sheet}',1)" ${page >= totalPages ? "disabled" : ""}>Next →</button>`;
  }
}
function changeTablePage(sheet, delta) {
  TABLE_PAGE[sheet] = (TABLE_PAGE[sheet] || 1) + delta;
  renderTable(sheet);
  document
    .getElementById("t-" + sheet)
    ?.closest(".tbl-wrap")
    ?.scrollTo({ top: 0, left: 0, behavior: "auto" });
}

