function renderAtt() {
  /* attendance handled by ATT system */
}

// ── FREIGHT ──
let frQ = "";
function moveFreightRateActionsToHeader() {
  const actions = document.getElementById("fr-rate-actions");
  const header = document.querySelector("#cp-fr .pg-hdr");
  if (actions && header && actions.parentElement !== header) {
    header.appendChild(actions);
  }
}
function filterFr(q) {
  frQ = q;
  renderFr();
}
function renderFr() {
  moveFreightRateActionsToHeader();
  const g = document.getElementById("frGrid");
  if (!g) return;
  const rows = STATE.fr.filter(
    (r) => !frQ || r.destination.toLowerCase().includes(frQ.toLowerCase()),
  );
  g.innerHTML =
    rows
      .map((r, _) => {
        const ri = STATE.fr.indexOf(r);
        return `<div class="fr-card">
      <div class="fr-dest">${r.destination}</div>
      <div style="display:flex;align-items:center;gap:.3rem">
        <div class="fr-rate">₹${r.rate}</div>
        <div class="fr-acts"><button class="act-btn act-edit icon-only" title="Edit" aria-label="Edit" onclick="askEdit('fr',${ri})">✏️</button>${isUserAdmin() ? `<button class="act-btn act-del icon-only" title="Delete" aria-label="Delete" onclick="askDelete('fr',${ri})">🗑️</button>` : `<button class="act-btn act-del icon-only" title="Delete (Admin only)" disabled style="opacity:0.5;cursor:not-allowed">🗑️</button>`}</div>
      </div>
    </div>`;
      })
      .join("") ||
    '<div style="opacity:.35;padding:2rem">No destinations found.</div>';
  const cnt = document.getElementById("cnt-fr");
  if (cnt) cnt.textContent = `${rows.length} / ${STATE.fr.length}`;
  document.getElementById("nb-fr").textContent = STATE.fr.length;
  document.getElementById("fr-sub").textContent =
    `${STATE.fr.length} destinations`;
  document.getElementById("k-fr").textContent = STATE.fr.length;
}

// ── FILTER ──
function filterTbl(sheet, q) {
  filterQ[sheet] = q;
  TABLE_PAGE[sheet] = 1;
  renderTable(sheet);
}
function filterByCol(sheet, col, val) {
  if (!filterCol[sheet]) filterCol[sheet] = {};
  filterCol[sheet][col] = val;
  TABLE_PAGE[sheet] = 1;
  renderTable(sheet);
}
function globalSearch(q) {
  navById("cp-inv");
  filterQ.inv = q;
  TABLE_PAGE.inv = 1;
  renderTable("inv");
}
function showPending() {
  const p = STATE.pay.filter((r) =>
    (r["Payment Status"] || "").toLowerCase().includes("pending"),
  );
  toast(`⏳ ${p.length} pending payments`, "var(--yellow)");
}

// ── MONTH-WISE DATA HELPERS ──
function srtMonthKey(value) {
  const v = String(value || "").trim();
  if (!v || v === "-") return "";
  const iso = v.match(/^(\d{4})-(\d{2})/);
  if (iso) return `${iso[1]}-${iso[2]}`;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return "";
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}
function srtMonthLabel(key) {
  if (!/^\d{4}-\d{2}$/.test(String(key || ""))) return "Unknown";
  const [y, m] = key.split("-").map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString("en-IN", {
    month: "long",
    year: "numeric",
  });
}
function srtMoneyFull(n) {
  const num = Number(n) || 0;
  return "₹" + num.toLocaleString("en-IN", { maximumFractionDigits: 2 });
}
function srtSyncMonthSelect(id, keys, requested) {
  const sel = document.getElementById(id);
  if (!sel) return "";
  const old = requested || sel.value;
  sel.innerHTML = keys.length
    ? keys
        .map((k) => `<option value="${k}">${srtMonthLabel(k)}</option>`)
        .join("")
    : '<option value="">No month data</option>';
  const chosen = keys.includes(old) ? old : keys[0] || "";
  sel.value = chosen;
  return chosen;
}
function gpsRenderMonthly(requestedMonth) {
  const records =
    typeof GPSD !== "undefined" && Array.isArray(GPSD.records)
      ? GPSD.records
      : [];
  const grouped = {};
  records.forEach((r) => {
    const key = srtMonthKey(r.dateIssued);
    if (!key) return;
    const g =
      grouped[key] ||
      (grouped[key] = {
        issued: 0,
        charged: 0,
        returnedAmount: 0,
        late: 0,
        balance: 0,
        pending: 0,
      });
    g.issued++;
    g.charged += Number(r.gpsAmount) || 0;
    g.returnedAmount += Number(r.amountReturn) || 0;
    g.late += Number(r.lateFee) || 0;
    g.balance += Number(r.balanceDue) || 0;
    if (String(r.gpsReturn || "").toLowerCase() !== "yes") g.pending++;
  });
  const keys = Object.keys(grouped).sort().reverse();
  const selected = srtSyncMonthSelect("gpsMonthSelect", keys, requestedMonth);
  const g = grouped[selected] || {
    issued: 0,
    charged: 0,
    returnedAmount: 0,
    late: 0,
    balance: 0,
    pending: 0,
  };
  const set = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };
  set("gpsMonIssued", g.issued);
  set("gpsMonCharged", srtMoneyFull(g.charged));
  set("gpsMonReturnedAmt", srtMoneyFull(g.returnedAmount));
  set("gpsMonLate", srtMoneyFull(g.late));
  set("gpsMonBalance", srtMoneyFull(g.balance));
  set("gpsMonPending", g.pending);
  const body = document.getElementById("gpsMonthSummaryBody");
  if (body)
    body.innerHTML = keys.length
      ? keys
          .map((k) => {
            const x = grouped[k];
            return `<tr class="${k === selected ? "month-active" : ""}" onclick="document.getElementById('gpsMonthSelect').value='${k}';gpsRenderMonthly('${k}')"><td><strong>${srtMonthLabel(k)}</strong></td><td>${x.issued}</td><td>${srtMoneyFull(x.charged)}</td><td>${srtMoneyFull(x.returnedAmount)}</td><td>${srtMoneyFull(x.late)}</td><td>${srtMoneyFull(x.balance)}</td><td>${x.pending}</td></tr>`;
          })
          .join("")
      : '<tr><td colspan="7" class="month-empty">No valid GPS month data available.</td></tr>';
}
function expMonthlyGroups() {
  const grouped = {};
  (STATE.exp || []).forEach((r) => {
    const key = srtMonthKey(r.Date);
    if (!key) return;
    const amount = Number.parseFloat(r.Expense || r.amount || 0) || 0;
    const g =
      grouped[key] ||
      (grouped[key] = { entries: 0, total: 0, highest: 0, remarks: {} });
    g.entries++;
    g.total += amount;
    g.highest = Math.max(g.highest, amount);
    const remark = String(r.Remark || "").trim();
    if (remark && remark !== "-") {
      const norm = remark.toLowerCase();
      if (!g.remarks[norm]) g.remarks[norm] = { label: remark, count: 0 };
      g.remarks[norm].count++;
    }
  });
  return grouped;
}
function renderExpMonthly(requestedMonth) {
  const grouped = expMonthlyGroups();
  const keys = Object.keys(grouped).sort().reverse();
  const selected = srtSyncMonthSelect("expMonthSelect", keys, requestedMonth);
  const topRemark = (g) => {
    const arr = Object.values(g?.remarks || {}).sort(
      (a, b) => b.count - a.count || a.label.localeCompare(b.label),
    );
    return arr[0]?.label || "—";
  };
  const g = grouped[selected] || {
    entries: 0,
    total: 0,
    highest: 0,
    remarks: {},
  };
  const avg = g.entries ? g.total / g.entries : 0;
  const set = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };
  set("expMonTotal", srtMoneyFull(g.total));
  set("expMonEntries", g.entries);
  set("expMonAvg", srtMoneyFull(avg));
  set("expMonHighest", srtMoneyFull(g.highest));
  set("expMonTopRemark", topRemark(g));
  const body = document.getElementById("expMonthSummaryBody");
  if (body)
    body.innerHTML = keys.length
      ? keys
          .map((k) => {
            const x = grouped[k],
              a = x.entries ? x.total / x.entries : 0;
            return `<tr class="${k === selected ? "month-active" : ""}" onclick="document.getElementById('expMonthSelect').value='${k}';renderExpMonthly('${k}')"><td><strong>${srtMonthLabel(k)}</strong></td><td>${x.entries}</td><td>${srtMoneyFull(x.total)}</td><td>${srtMoneyFull(a)}</td><td>${srtMoneyFull(x.highest)}</td><td>${topRemark(x)}</td></tr>`;
          })
          .join("")
      : '<tr><td colspan="6" class="month-empty">No valid expense month data available.</td></tr>';
}

// ── EXPENSE STATS ──
function updateExpStats() {
  const amounts = STATE.exp.map(
    (r) => parseFloat(r.Expense || r.amount || 0) || 0,
  );
  const total = amounts.reduce((s, v) => s + v, 0);
  const avg = amounts.length ? Math.round(total / amounts.length) : 0;
  document.getElementById("exp-total").textContent = inr(total);
  document.getElementById("exp-count").textContent = STATE.exp.length;
  document.getElementById("exp-avg").textContent = inr(avg);
  document.getElementById("k-exp").textContent = inr(total);
  document.getElementById("ks-exp").textContent = `${STATE.exp.length} entries`;
  document.getElementById("nb-exp").textContent = STATE.exp.length;
  renderExpMonthly();
}

// ── KPI UPDATE ──
function flashKpi(id) {
  const e = document.getElementById(id);
  if (!e) return;
  e.classList.remove("flash");
  void e.offsetWidth;
  e.classList.add("flash");
}
function bumpBadge(id) {
  const e = document.getElementById(id);
  if (!e) return;
  e.classList.remove("bump");
  void e.offsetWidth;
  e.classList.add("bump");
}

function updateKPIs(changed) {
  const totalMT = STATE.inv.reduce((s, r) => s + (parseFloat(r["MT"]) || 0), 0);
  const advanceTot = STATE.pay.reduce(
    (s, r) => s + (parseFloat(r["Payment Advance AMT"]) || 0),
    0,
  );
  const finalTot = STATE.pay.reduce(
    (s, r) => s + (parseFloat(r["Payment Final AMT"]) || 0),
    0,
  );
  const kpiMoney = (n) =>
    n >= 10000000
      ? "₹" + (n / 10000000).toFixed(2) + "Cr"
      : n >= 100000
        ? "₹" + (n / 100000).toFixed(2) + "L"
        : "₹" + n.toLocaleString("en-IN", { maximumFractionDigits: 2 });
  document.getElementById("k-inv").textContent = totalMT.toLocaleString(
    "en-IN",
    { maximumFractionDigits: 2 },
  );
  document.getElementById("ks-inv").textContent =
    `${STATE.inv.length} invoice records`;
  document.getElementById("k-payc").textContent = kpiMoney(advanceTot);
  document.getElementById("k-pend").textContent = kpiMoney(finalTot);
  document.getElementById("ks-pay").textContent =
    `${STATE.pay.length} payment records`;
  const cpTot = STATE.cp.reduce(
    (s, r) => s + (parseFloat(r["Total Amount"]) || 0),
    0,
  );
  document.getElementById("k-cp").textContent = inr(cpTot);
  document.getElementById("ks-cp").textContent = `${STATE.cp.length} records`;
  document.getElementById("k-gps").textContent =
    typeof GPSD !== "undefined" ? GPSD.records.length : STATE.gps.length;
  updateExpStats();
  if (changed) {
    flashKpi("kpi-" + changed);
    bumpBadge("nb-" + changed);
  }
  if (changed === "pay") {
    flashKpi("kpi-pend");
  }
  if (changed === "inv") {
    drawBar();
    drawTreemap();
  }
}

// ── CHARTS ──
function computeMonthly() {
  const m = {};
  STATE.inv.forEach((r) => {
    const mt = parseFloat(r["MT"]) || 0;
    if (!mt) return;
    const ds = r["Loading Date"] || "";
    const d = new Date(ds);
    if (isNaN(d)) return;
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
    const lbl =
      d.toLocaleString("en-IN", { month: "short" }) + " " + d.getFullYear();
    if (!m[key]) m[key] = { label: lbl, mt: 0 };
    m[key].mt += mt;
  });
  return Object.keys(m)
    .sort()
    .map((k) => ({ month: m[k].label, mt: m[k].mt }));
}
function drawBar() {
  const data = computeMonthly();
  const chart = document.getElementById("barChart");
  const labels = document.getElementById("barLabels");
  const range = document.getElementById("chartRange");
  if (!data.length) {
    chart.innerHTML =
      '<div style="opacity:.3;padding:1rem;font-size:.8rem">No dated MT dispatch records yet.</div>';
    labels.innerHTML = "";
    if (range) range.textContent = "No dispatch data";
    return;
  }
  const max = Math.max(...data.map((x) => x.mt), 1);
  chart.innerHTML = data
    .map((x) => {
      const h = Math.max(3, Math.round((x.mt / max) * 118));
      const mt = x.mt.toLocaleString("en-IN", { maximumFractionDigits: 2 });
      return `<div class="bcg"><div class="bcb" style="height:${h}px;background:var(--orange)"></div><div class="bc-tip">📅 ${x.month}<br>Dispatch: ${mt} MT</div></div>`;
    })
    .join("");
  labels.innerHTML = data
    .map((x) => `<div class="bcl">${x.month.replace(/\s\d{4}/, "")}</div>`)
    .join("");
  if (range)
    range.textContent =
      data.length > 1
        ? data[0].month + " – " + data[data.length - 1].month
        : data[0].month;
}
function drawTreemap() {
  const chart = document.getElementById("treemapChart");
  const totalEl = document.getElementById("treemapTotal");
  const rootEl = document.getElementById("treemapRootLabel");
  if (!chart) return;

  const cityMap = {};
  STATE.inv.forEach((r) => {
    const raw = String(r["Destination City"] || "").trim();
    const mt = parseFloat(r["MT"]) || 0;
    if (!raw || raw === "-" || !mt) return;
    const key = raw.toLowerCase().replace(/\s+/g, " ");
    if (!cityMap[key])
      cityMap[key] = {
        name: key.replace(/\b\w/g, (ch) => ch.toUpperCase()),
        value: 0,
      };
    cityMap[key].value += mt;
  });

  const items = Object.values(cityMap).sort((a, b) => b.value - a.value);
  // Expand the treemap canvas as the number of cities grows so all city/MT labels stay visible.
  chart.style.height = Math.max(520, Math.ceil(items.length / 6) * 90) + "px";
  const totalMT = items.reduce((sum, item) => sum + item.value, 0);
  const totalLabel = totalMT.toLocaleString("en-IN", {
    maximumFractionDigits: 1,
  });
  if (totalEl)
    totalEl.textContent = `${items.length} cities · ${totalLabel} MT`;
  if (rootEl) rootEl.textContent = `ALL DESTINATION CITIES · ${totalLabel} MT`;

  if (!items.length) {
    chart.innerHTML = '<div class="tm-empty">No city MT data available.</div>';
    return;
  }

  // Hierarchical treemap: root (all cities) → destination-city leaves.
  // Recursive binary partition keeps larger MT cities visually dominant.
  const rects = [];
  function split(nodes, x, y, w, h, depth) {
    if (!nodes.length) return;
    if (nodes.length === 1) {
      rects.push({ ...nodes[0], x, y, w, h, depth });
      return;
    }
    const sum = nodes.reduce((acc, node) => acc + node.value, 0);
    let acc = 0,
      cut = 1,
      best = Infinity;
    for (let i = 0; i < nodes.length - 1; i++) {
      acc += nodes[i].value;
      const diff = Math.abs(sum / 2 - acc);
      if (diff < best) {
        best = diff;
        cut = i + 1;
      }
    }
    const first = nodes.slice(0, cut),
      second = nodes.slice(cut);
    const firstSum = first.reduce((acc, node) => acc + node.value, 0);
    const ratio = sum ? firstSum / sum : 0.5;
    if (w >= h) {
      const firstW = w * ratio;
      split(first, x, y, firstW, h, depth + 1);
      split(second, x + firstW, y, w - firstW, h, depth + 1);
    } else {
      const firstH = h * ratio;
      split(first, x, y, w, firstH, depth + 1);
      split(second, x, y + firstH, w, h - firstH, depth + 1);
    }
  }
  split(items, 0, 0, 100, 100, 0);

  const colors = [
    "#FF4500",
    "#00A6D8",
    "#159947",
    "#C9A900",
    "#6765C8",
    "#D05E16",
    "#B85AC5",
    "#118B80",
    "#4A87D4",
    "#C93657",
    "#7B9F25",
    "#C27A08",
  ];
  chart.innerHTML = rects
    .map((r, i) => {
      const area = r.w * r.h;
      const cls = area < 45 ? " tm-tiny" : area < 130 ? " tm-small" : "";
      const mt = r.value.toLocaleString("en-IN", { maximumFractionDigits: 2 });
      const share = ((r.value / totalMT) * 100).toFixed(1);
      const title = `${r.name}: ${mt} MT (${share}%)`;
      return `<div class="tm-cell${cls}" title="${title}" style="left:${r.x}%;top:${r.y}%;width:${r.w}%;height:${r.h}%;background:${colors[i % colors.length]};"><div class="tm-inner"><div class="tm-city">${r.name}</div><div><div class="tm-mt">${mt} MT</div><div class="tm-share">${share}% of total</div></div></div></div>`;
    })
    .join("");
}

// ── RECEIVED PAYMENT HELPERS ──
function saveReceivedPaymentData() {
  try {
    localStorage.setItem(
      "srt_received_payment_v1",
      JSON.stringify(STATE.rp || []),
    );
  } catch (e) {}
}
function rpDateInputValue(v) {
  const s = String(v || "").trim();
  if (!s || s === "-") return "";
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const d = new Date(s);
  if (isNaN(d)) return "";
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function rpUpdateRemaining(fields) {
  const ii = fields.findIndex((f) => f.k === "Invoice Amount"),
    ri = fields.findIndex((f) => f.k === "Received Amount"),
    mi = fields.findIndex((f) => f.k === "Remaining Amount");
  if (ii < 0 || ri < 0 || mi < 0) return;
  const inv = parseFloat(document.getElementById("mf_" + ii)?.value),
    rec = parseFloat(document.getElementById("mf_" + ri)?.value),
    out = document.getElementById("mf_" + mi);
  if (!out) return;
  out.value =
    !isNaN(inv) && !isNaN(rec)
      ? String(Math.round((inv - rec) * 100) / 100)
      : "";
}
function rpAutofillFromInvoice(invoiceNumber, fields) {
  const value = String(invoiceNumber || "")
    .trim()
    .toLowerCase();
  if (!value) return;
  const inv = (STATE.inv || []).find(
    (r) =>
      String(r["Invoice no."] || "")
        .trim()
        .toLowerCase() === value,
  );
  if (!inv) return;
  const map = {
    "Loading Date": "Loading Date",
    "Vehicle Number": "Vehicle",
    "L.R.N.": "L. R. N.",
    MT: "MT",
    "Trader Name": "Trader Name",
    City: "Destination City",
    "DO Number": "DO Number",
    "Invoice Amount": "Bill Amount",
  };
  fields.forEach((f, i) => {
    const src = map[f.k];
    if (!src) return;
    const el = document.getElementById("mf_" + i);
    if (!el) return;
    let v = sv(inv[src]);
    if (f.k === "Loading Date") v = rpDateInputValue(v);
    if (v !== "-" && (!el.value || el.value === "-")) el.value = v;
  });
  rpUpdateRemaining(fields);
}

function saveFreightMasterData() {
  try {
    localStorage.setItem(
      "srt_trader_details_v1",
      JSON.stringify(STATE.trader || []),
    );
  } catch (e) {}
  try {
    localStorage.setItem(
      "srt_vehicle_details_v1",
      JSON.stringify(STATE.vehicle || []),
    );
  } catch (e) {}
}
function switchFreightSection(section) {
  const map = { rates: "Rates", traders: "Traders", vehicles: "Vehicles" };
  moveFreightRateActionsToHeader();
  const rateActions = document.getElementById("fr-rate-actions");
  if (rateActions) rateActions.hidden = section !== "rates";
  ["rates", "traders", "vehicles"].forEach((key) => {
    document
      .getElementById("frPanel" + map[key])
      ?.classList.toggle("active", key === section);
    document
      .getElementById("frTab" + map[key])
      ?.classList.toggle("active", key === section);
  });
  if (section === "traders") renderTable("trader");
  if (section === "vehicles") renderTable("vehicle");
  if (section === "rates") renderFr();
}

// ── MODAL ──
// Auto-build form fields from COLS (type detected from col name)
function colFormType(name) {
  const n = name.toLowerCase();
  if (n.includes("date")) return "date";
  if (
    n.includes("amount") ||
    n.includes("gst") ||
    n.includes("frieght") ||
    n.includes("freight") ||
    n.includes("total") ||
    n.includes("charges") ||
    n.includes("mt")
  )
    return "number";
  if (
    n.includes("status") ||
    n.includes("mode") ||
    n.includes("type") ||
    n.includes("upload") ||
    n.includes("pahuch")
  )
    return "select";
  if (n.includes("remark") || n.includes("link")) return "text";
  return "text";
}
const SELECT_OPTS = {
  "Invoice Status": ["Created", "Pending"],
  "Pahuch Status": ["Physical Copy received", "Image received", "Pending"],
  "Pahuch Upload Status": ["Submit to Plant", "Pending"],
  "Invoice Upload Status": ["Submit to Plant", "Pending"],
  "Vehicle Type": ["FOR - COMPANY", "X-PARTY"],
  "Truck Type": [
    "Pickup / Mini Truck",
    "LCV",
    "6 Wheeler",
    "10 Wheeler",
    "12 Wheeler",
    "14 Wheeler",
    "16 Wheeler",
    "18 Wheeler",
    "22 Wheeler",
    "Trailer",
    "Container",
    "Other",
  ],
  "Payment Status": ["Complete", "Pending", "Advance"],
  "Payment voucher status": ["Created", "Pending"],
  "Payment Mode Advance": ["Online", "Cash", "Pending"],
  "Payment Mode Final": ["Online", "Cash", "Pending"],
  "Submit Status": ["Complete", "Pending"],
  "GPS Type": ["SIM", "PHYSICAL"],
  "GPS Return": ["Yes", "No"],
};

function openModal(sheet, idx) {
  modalSheet = sheet;
  modalIdx = idx;
  const isEdit = idx !== null;
  const rec = isEdit ? STATE[sheet][idx] : {};
  const labels = {
    inv: "Invoice",
    pay: "Payment",
    cp: "Company Payment",
    rp: "Received Payment",
    gps: "GPS Vehicle",
    att: "Staff Attendance",
    exp: "Expense",
    fr: "Freight Rate",
    trader: "Trader",
    vehicle: "Vehicle / Owner",
  };
  document.getElementById("modalTitle").textContent =
    (isEdit ? "Edit " : "Add ") + labels[sheet];
  document.getElementById("modalBadge").textContent = isEdit
    ? "EDIT MODE"
    : "NEW RECORD";

  let fields = [];
  if (sheet === "att") {
    fields = [
      { k: "name", l: "Staff Name", type: "text" },
      { k: "present", l: "Present Days", type: "number" },
      { k: "wfh", l: "WFH Days", type: "number" },
      { k: "absent", l: "Absent Days", type: "number" },
      { k: "total", l: "Total Working Days", type: "number" },
    ];
  } else if (sheet === "rp") {
    fields = (COLS.rp || [])
      .filter((c) => c.k !== "Sr. No.")
      .map((c) => ({ k: c.k, l: c.l, type: colFormType(c.k) }));
  } else if (sheet === "fr") {
    fields = [
      { k: "destination", l: "Destination City", type: "text" },
      { k: "rate", l: "Rate ₹/MT", type: "number" },
    ];
  } else {
    const cols = COLS[sheet] || [];
    fields = cols
      .filter((c) => c.k !== "Sr. No." && c.k !== "sr")
      .map((c) => ({
        k: c.k,
        l: c.l,
        type:
          sheet === "vehicle" && c.k === "RC Image" ? "file" : colFormType(c.k),
      }));
  }

  const formHtml = fields
    .map((f, i) => {
      const fid = "mf_" + i;
      const val = isEdit ? sv(rec[f.k]) : "";
      const full =
        (f.type === "text" && f.l.toLowerCase().includes("remark")) ||
        f.l.toLowerCase().includes("link");
      const cls = full ? "mfg full" : "mfg";
      let inp = "";
      if (f.type === "file") {
        const hasImage =
          typeof val === "string" && val.startsWith("data:image/");
        inp = `<input type="file" id="${fid}" accept="image/png,image/jpeg,image/webp" onchange="srtHandleVehicleRcImage(this,'${fid}_preview')">
        <div class="srt-rc-upload-help">Upload JPG, PNG or WebP. Image is optimized before saving.</div>
        <div class="srt-rc-preview" id="${fid}_preview">${hasImage ? `<img src="${val}" alt="RC image preview">` : "<span>No RC image uploaded</span>"}</div>
        <button type="button" class="srt-rc-remove" onclick="srtRemoveVehicleRcImage('${fid}','${fid}_preview')">Remove RC Image</button>`;
      } else if (f.type === "select" && SELECT_OPTS[f.k]) {
        const opts = SELECT_OPTS[f.k]
          .map(
            (o) =>
              `<option value="${o}"${val === o ? " selected" : ""}>${o}</option>`,
          )
          .join("");
        inp = `<select id="${fid}"><option value="">— Select —</option>${opts}</select>`;
      } else if (full) {
        inp = `<input type="text" id="${fid}" value="${val === "-" ? "" : val.replace(/"/g, "&quot;")}" placeholder="${f.l}">`;
      } else {
        inp = `<input type="${f.type || "text"}" id="${fid}" value="${val === "-" ? "" : val.replace(/"/g, "&quot;")}" placeholder="${f.l}">`;
      }
      return `<div class="${cls}"><label>${f.l}</label>${inp}</div>`;
    })
    .join("");

  document.getElementById("modalForm").innerHTML = formHtml;
  document.getElementById("modalForm")._fields = fields;
  if (sheet === "vehicle") {
    fields.forEach((f, i) => {
      const el = document.getElementById("mf_" + i);
      if (!el) return;
      if (f.k === "PAN Number") {
        el.maxLength = 10;
        el.style.textTransform = "uppercase";
        el.addEventListener("input", () => {
          el.value = el.value
            .toUpperCase()
            .replace(/[^A-Z0-9]/g, "")
            .slice(0, 10);
        });
      }
      if (f.k === "Aadhaar Number") {
        el.maxLength = 12;
        el.inputMode = "numeric";
        el.addEventListener("input", () => {
          el.value = el.value.replace(/\D/g, "").slice(0, 12);
        });
      }
      if (f.type === "file") {
        const existing =
          isEdit &&
          typeof rec[f.k] === "string" &&
          rec[f.k].startsWith("data:image/")
            ? rec[f.k]
            : "-";
        el.dataset.existing = existing;
        el.dataset.dataUrl = "";
        el.dataset.reading = "0";
      }
    });
  }
  if (sheet === "rp") {
    const invIndex = fields.findIndex((f) => f.k === "Invoice Number");
    if (invIndex >= 0) {
      const invInput = document.getElementById("mf_" + invIndex);
      if (invInput) {
        invInput.setAttribute("list", "rpInvoiceNumberList");
        invInput.addEventListener("change", () =>
          rpAutofillFromInvoice(invInput.value, fields),
        );
        invInput.addEventListener("blur", () =>
          rpAutofillFromInvoice(invInput.value, fields),
        );
      }
      const list = document.createElement("datalist");
      list.id = "rpInvoiceNumberList";
      const seen = new Set();
      (STATE.inv || []).forEach((r) => {
        const v = sv(r["Invoice no."]);
        if (v !== "-" && !seen.has(v)) {
          seen.add(v);
          const o = document.createElement("option");
          o.value = v;
          list.appendChild(o);
        }
      });
      document.getElementById("modalForm").appendChild(list);
    }
    const remIndex = fields.findIndex((f) => f.k === "Remaining Amount");
    const invoiceAmtIndex = fields.findIndex((f) => f.k === "Invoice Amount");
    const receivedAmtIndex = fields.findIndex((f) => f.k === "Received Amount");
    const remInput =
      remIndex >= 0 ? document.getElementById("mf_" + remIndex) : null;
    if (remInput) {
      remInput.readOnly = true;
      remInput.tabIndex = -1;
      remInput.style.opacity = ".75";
      remInput.title =
        "Automatically calculated: Invoice Amount − Received Amount";
    }
    [invoiceAmtIndex, receivedAmtIndex].forEach((i) => {
      if (i >= 0)
        document
          .getElementById("mf_" + i)
          ?.addEventListener("input", () => rpUpdateRemaining(fields));
    });
    rpUpdateRemaining(fields);
  }
  document.getElementById("modalOverlay").classList.add("open");
  document.querySelector(".modal-body").scrollTop = 0;
}
function closeModal() {
  document.getElementById("modalOverlay").classList.remove("open");
}

function srtHandleVehicleRcImage(input, previewId) {
  const file = input?.files?.[0];
  if (!file) return;
  if (!/^image\/(jpeg|png|webp)$/i.test(file.type || "")) {
    toast("RC Image must be JPG, PNG or WebP.", "var(--red)");
    input.value = "";
    return;
  }
  if (file.size > 8 * 1024 * 1024) {
    toast("RC Image must be 8 MB or smaller.", "var(--red)");
    input.value = "";
    return;
  }
  input.dataset.reading = "1";
  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new Image();
    img.onload = () => {
      try {
        const maxW = 1200,
          maxH = 900,
          scale = Math.min(1, maxW / img.width, maxH / img.height);
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(img.width * scale));
        canvas.height = Math.max(1, Math.round(img.height * scale));
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        const data = canvas.toDataURL("image/jpeg", 0.78);
        input.dataset.dataUrl = data;
        input.dataset.reading = "0";
        const p = document.getElementById(previewId);
        if (p) p.innerHTML = `<img src="${data}" alt="RC image preview">`;
        toast("RC image ready to save.", "var(--green)");
      } catch (err) {
        input.dataset.reading = "0";
        toast("Could not process RC image.", "var(--red)");
      }
    };
    img.onerror = () => {
      input.dataset.reading = "0";
      toast("Could not read RC image.", "var(--red)");
    };
    img.src = e.target.result;
  };
  reader.onerror = () => {
    input.dataset.reading = "0";
    toast("Could not read RC image.", "var(--red)");
  };
  reader.readAsDataURL(file);
}
function srtRemoveVehicleRcImage(inputId, previewId) {
  const input = document.getElementById(inputId);
  if (!input) return;
  input.value = "";
  input.dataset.dataUrl = "-";
  input.dataset.existing = "-";
  input.dataset.reading = "0";
  const p = document.getElementById(previewId);
  if (p) p.innerHTML = "<span>No RC image uploaded</span>";
}

function saveModal() {
  const fields = document.getElementById("modalForm")._fields || [];
  const rec = {};
  for (let i = 0; i < fields.length; i++) {
    const f = fields[i],
      el = document.getElementById("mf_" + i);
    if (f.type === "file") {
      if (el?.dataset?.reading === "1") {
        toast(
          "Please wait for the RC image to finish processing.",
          "var(--yellow)",
        );
        return;
      }
      rec[f.k] =
        el?.dataset?.dataUrl && el.dataset.dataUrl !== ""
          ? el.dataset.dataUrl
          : el?.dataset?.existing || "-";
    } else {
      rec[f.k] = el ? el.value.trim() || "-" : "-";
    }
  }
  if (modalSheet === "vehicle") {
    const pan = String(rec["PAN Number"] || "")
      .toUpperCase()
      .replace(/\s/g, "");
    const aadhaar = String(rec["Aadhaar Number"] || "").replace(/\D/g, "");
    rec["PAN Number"] = pan && pan !== "-" ? pan : "-";
    rec["Aadhaar Number"] = aadhaar || "-";
    if (
      rec["PAN Number"] !== "-" &&
      !/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(rec["PAN Number"])
    ) {
      toast(
        "PAN Number must be in valid format, for example ABCDE1234F.",
        "var(--red)",
      );
      return;
    }
    if (
      rec["Aadhaar Number"] !== "-" &&
      !/^\d{12}$/.test(rec["Aadhaar Number"])
    ) {
      toast("Aadhaar Number must contain exactly 12 digits.", "var(--red)");
      return;
    }
  }
  if (modalSheet === "rp") {
    const invoice = parseFloat(rec["Invoice Amount"]);
    const received = parseFloat(rec["Received Amount"]);
    rec["Remaining Amount"] =
      !isNaN(invoice) && !isNaN(received)
        ? String(Math.round((invoice - received) * 100) / 100)
        : "-";
  }
  if (modalIdx !== null) {
    const old = STATE[modalSheet][modalIdx];
    ["Sr. No.", "sr"].forEach((k) => {
      if (old[k] !== undefined) rec[k] = old[k];
    });
    STATE[modalSheet][modalIdx] = rec;
    newRowIdx = modalIdx;
    toast("✅ Record updated — dashboard refreshed", "var(--green)");
  } else {
    let srKey =
      STATE[modalSheet].length > 0
        ? Object.keys(STATE[modalSheet][0]).find(
            (k) => k === "Sr. No." || k === "sr",
          )
        : null;
    if (["rp", "trader", "vehicle"].includes(modalSheet)) srKey = "Sr. No.";
    if (srKey) rec[srKey] = String(STATE[modalSheet].length + 1);
    STATE[modalSheet].push(rec);
    clearTableClearedMarker(modalSheet);
    newRowIdx = STATE[modalSheet].length - 1;
    if (TABLE_PAGE[modalSheet] !== undefined) TABLE_PAGE[modalSheet] = 1;
    toast(`✅ Added — dashboard updated!`, "var(--green)");
  }
  if (modalSheet === "rp") saveReceivedPaymentData();
  if (modalSheet === "trader" || modalSheet === "vehicle")
    saveFreightMasterData();
  closeModal();
  renderAll(modalSheet);
}

// ── DELETE ──
function isUserAdmin() {
  return SRT_CURRENT_USER && SRT_CURRENT_USER.role === "admin";
}

let recordAuthAction = null;
let recordAuthBusy = false;
function askEdit(sheet, idx) {
  if (isUserAdmin()) {
    openModal(sheet, idx);
    return;
  }
  openRecordAuthorization("edit", () => openModal(sheet, idx));
}
function openRecordAuthorization(action, onAuthorized) {
  if (isUserAdmin()) {
    onAuthorized();
    return;
  }
  recordAuthAction = { action, onAuthorized };
  const label = action === "delete" ? "delete this record" : "edit this record";
  document.getElementById("recordAuthTitle").textContent =
    action === "delete" ? "Authorize Record Deletion" : "Authorize Record Edit";
  document.getElementById("recordAuthMessage").textContent =
    `Enter your login credentials to ${label}.`;
  document.getElementById("recordAuthConfirm").checked = false;
  document.getElementById("recordAuthPassword").value = "";
  document.getElementById("recordAuthError").textContent = "";
  document.getElementById("recordAuthOverlay").classList.add("open");
  document.getElementById("recordAuthEmail").value =
    SRT_CURRENT_USER?.email || "";
  document.getElementById("recordAuthPassword").focus();
}
function closeRecordAuthorization() {
  if (recordAuthBusy) return;
  document.getElementById("recordAuthOverlay").classList.remove("open");
  recordAuthAction = null;
}
async function confirmRecordAuthorization() {
  if (!recordAuthAction || recordAuthBusy) return;
  const email = document
    .getElementById("recordAuthEmail")
    .value.trim()
    .toLowerCase();
  const currentEmail = String(SRT_CURRENT_USER?.email || "")
    .trim()
    .toLowerCase();
  const password = document.getElementById("recordAuthPassword").value;
  const confirmed = document.getElementById("recordAuthConfirm").checked;
  const error = document.getElementById("recordAuthError");
  if (!email || !password) {
    error.textContent = "Login ID and password are required.";
    return;
  }
  if (email !== currentEmail) {
    error.textContent = "Use the login ID of the currently signed-in user.";
    return;
  }
  if (!confirmed) {
    error.textContent = `Check the box to confirm you want to ${recordAuthAction.action} this record.`;
    return;
  }
  recordAuthBusy = true;
  const button = document.getElementById("recordAuthSubmit");
  button.disabled = true;
  button.textContent = "Verifying...";
  try {
    const login = await SrtApi.login(email, password);
    const profileResponse = await fetch("/api/auth/me", {
      headers: { Authorization: `Bearer ${login.access_token}` },
    });
    if (!profileResponse.ok)
      throw Object.assign(new Error("Invalid credentials."), {
        status: profileResponse.status,
      });
    const profile = await profileResponse.json();
    if (
      recordAuthAction.action === "delete" &&
      profile.user?.role !== "admin"
    ) {
      throw Object.assign(
        new Error("Administrator credentials are required for deletion."),
        { status: 403 },
      );
    }
    const callback = recordAuthAction.onAuthorized;
    document.getElementById("recordAuthOverlay").classList.remove("open");
    recordAuthAction = null;
    callback();
  } catch (err) {
    error.textContent =
      err.status === 403 ? err.message : "Invalid login ID or password.";
  } finally {
    recordAuthBusy = false;
    button.disabled = false;
    button.textContent = "Authorize";
  }
}

function askDelete(sheet, idx) {
  if (!isUserAdmin()) {
    toast(
      "❌ Admin only: Only administrators can delete records",
      "var(--red)",
    );
    return;
  }
  deleteTarget = { sheet, idx };
  const r = STATE[sheet][idx];
  const name =
    r.name ||
    r.Name ||
    r["Trader Name"] ||
    r["Invoice no."] ||
    r["Invoice No."] ||
    r["Vehicle number"] ||
    r.vehicle ||
    r.destination ||
    "this record";
  document.getElementById("delMsg").textContent =
    `Delete "${name}"? This cannot be undone.`;
  document.getElementById("delOverlay").classList.add("open");
}
function closeDelete() {
  document.getElementById("delOverlay").classList.remove("open");
  deleteTarget = null;
}
function confirmDelete() {
  if (!deleteTarget) return;
  const { sheet, idx } = deleteTarget;
  STATE[sheet].splice(idx, 1);
  const srKey =
    STATE[sheet].length > 0
      ? Object.keys(STATE[sheet][0]).find((k) => k === "Sr. No." || k === "sr")
      : null;
  if (srKey) STATE[sheet].forEach((r, i) => (r[srKey] = String(i + 1)));
  if (sheet === "rp") saveReceivedPaymentData();
  if (sheet === "trader" || sheet === "vehicle") saveFreightMasterData();
  closeDelete();
  renderAll(sheet);
  toast("🗑 Record deleted — dashboard updated", "var(--red)");
}

// ── DELETE ALL ──
let deleteAllSheet = null;
function askDeleteAll(sheet) {
  if (!SRT_CURRENT_USER || SRT_CURRENT_USER.role !== "admin") {
    toast(
      "❌ Admin only: Only administrators can delete all records",
      "var(--red)",
    );
    return;
  }
  const sheetLabel =
    {
      inv: "Invoices",
      pay: "Payments",
      cp: "Company Payments",
      rp: "Received Payments",
      exp: "Expenses",
      fr: "Freight Rates",
      trader: "Traders",
      vehicle: "Vehicles",
    }[sheet] || sheet;
  const count = STATE[sheet]?.length || 0;
  deleteAllSheet = sheet;
  const countText = count === 0 ? "all currently stored" : `${count}`;
  document.getElementById("delAllMsg").textContent =
    `Delete ALL ${countText} ${sheetLabel} records? This CANNOT be undone.`;
  document.getElementById("delAllOverlay").classList.add("open");
}
function closeDeleteAll() {
  document.getElementById("delAllOverlay").classList.remove("open");
  deleteAllSheet = null;
}
async function confirmDeleteAll() {
  if (!deleteAllSheet) return;
  const sheet = deleteAllSheet;
  const endpoint = `/api/${{ inv: "invoices", pay: "payments", cp: "company-payments", rp: "received-payments", exp: "expenses", fr: "freight-rates", trader: "traders", vehicle: "vehicles" }[sheet]}/delete-all/confirm`;
  console.log("Delete all endpoint:", endpoint);

  try {
    const res = await SrtApi.del(endpoint);
    console.log("Delete all response:", res);
    STATE[sheet] = [];
    markTableCleared(sheet);
    if (sheet === "rp") saveReceivedPaymentData();
    if (sheet === "trader" || sheet === "vehicle") saveFreightMasterData();
    closeDeleteAll();
    renderAll(sheet);
    const msg = `✅ Deleted ${res.deleted_count || "all"} ${sheet} records from database`;
    console.log(msg);
    toast(msg, "var(--green)");
  } catch (err) {
    console.error("Delete all error:", err);
    if (err.status === 403) {
      toast(`❌ Admin access required: ${err.message}`, "var(--red)");
    } else if (err.status === 401) {
      toast(`❌ Not authenticated. Please login again.`, "var(--red)");
    } else {
      toast(`❌ Delete failed: ${err.message}`, "var(--red)");
    }
  }
}

// ── CSV ──
function exportCSV(sheet) {
  let rows, header, lines;
  if (sheet === "fr") {
    rows = STATE.fr;
    header = "Destination,Rate";
    lines = rows.map((r) => `"${r.destination}","${r.rate}"`);
  } else if (sheet === "att") {
    rows = STATE.att;
    header = "Name,Present,WFH,Absent,Total";
    lines = rows.map(
      (r) => `"${r.name}",${r.present},${r.wfh},${r.absent},${r.total}`,
    );
  } else {
    rows = visRows(sheet);
    const cols = COLS[sheet];
    header = cols.map((c) => c.l).join(",");
    lines = rows.map((r) =>
      cols
        .map((c) => {
          const raw = r[c.k];
          const out = c.image
            ? typeof raw === "string" && raw.startsWith("data:image/")
              ? "Uploaded"
              : "Not Uploaded"
            : sv(raw);
          return `"${String(out).replace(/"/g, '""')}"`;
        })
        .join(","),
    );
  }
  const csv = [header, ...lines].join("\n");
  const a = document.createElement("a");
  a.href = "data:text/csv;charset=utf-8," + encodeURIComponent(csv);
  a.download = `SRT_${sheet}_${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  toast("⬇ CSV exported", "var(--cyan)");
}

// ── RENDER ALL ──
function renderAll(changed) {
  newRowIdx = -1;
  ["inv", "pay", "cp", "rp", "exp", "trader", "vehicle"].forEach(
    renderTable,
  ); /* gps handled by GPS system */
  renderAtt();
  renderFr();
  updateKPIs(changed);
  drawTreemap();
  if (typeof renderHomeDispatchCities === "function")
    renderHomeDispatchCities();
  if (!changed || changed === "inv") drawBar();
}
function initDash() {
  setTimeout(restoreSidebar, 50);
  drawBar();
  drawTreemap();
  renderAll(null);
  // Initialize subsystems with a slight delay so DOM is ready
  setTimeout(() => {
    if (typeof initAtt === "function") initAtt();
    if (typeof initGPS === "function") initGPS();
  }, 100);
  toast("✅ Dashboard loaded · Shree Ram Transport", "var(--green)");
}

// ════════════════════════════════════════
// ATTENDANCE MANAGEMENT SYSTEM
// ════════════════════════════════════════
// ════════════════════════════════════════
// CONSTANTS
// ════════════════════════════════════════
const SK = {
  STAFF: "srt_att_staff_v3",
  RECORDS: "srt_att_records_v3",
  HOLIDAYS: "srt_att_holidays_v1",
  CLEARED: "srt_att_history_cleared_v1",
};
const STATUSES = ["Present", "WFH", "Absent", "Late", "Half-Day"];
const STATUS_COLOR = {
  Present: "var(--present)",
  WFH: "var(--wfh)",
  Absent: "var(--absent)",
  Late: "var(--late)",
  "Half-Day": "var(--half)",
};
const STATUS_BG = {
  Present: "var(--present-bg)",
  WFH: "var(--wfh-bg)",
  Absent: "var(--absent-bg)",
  Late: "var(--late-bg)",
  "Half-Day": "var(--half-bg)",
};
const STATUS_ICON = {
  Present: "✓ Present",
  WFH: "⌂ WFH",
  Absent: "✗ Absent",
  Late: "⏰ Late",
  "Half-Day": "½ Half-Day",
};
const DEPTS = [
  "Operations",
  "Finance",
  "HR",
  "Admin",
  "Logistics",
  "Management",
  "Other",
];
const NOTE_OPTS = {
  WFH: ["Work from home"],
  Absent: [
    "Medical leave",
    "Personal leave",
    "Not available",
    "Family emergency",
  ],
  Late: ["Traffic delay", "15 mins late", "30 mins late", "Personal work"],
  "Half-Day": [
    "Morning half",
    "Afternoon half",
    "Medical appointment",
    "Personal work",
  ],
};

// ════════════════════════════════════════
// STATE
// ════════════════════════════════════════
let ATT = {
  staff: [],
  records: {}, // { 'YYYY-MM-DD': { staffId: { status, note } } }
  holidays: {}, // { 'YYYY-MM-DD': { name:'Company Holiday' } }
  date: todayStr(),
  tab: "attendance",
  calStaffId: null,
  calYear: new Date().getFullYear(),
  calMonth: new Date().getMonth(),
  salaryYear: new Date().getFullYear(),
  salaryMonth: new Date().getMonth(),
  salaryStaffId: null,
  staffQ: "",
  deptQ: "",
  editId: null,
  delId: null,
};

// ════════════════════════════════════════
// DATE HELPERS
// ════════════════════════════════════════
function todayStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function fmtDate(str) {
  const d = new Date(str + "T00:00:00");
  return d.toLocaleDateString("en-IN", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}
function fmtMonthYear(y, m) {
  return new Date(y, m, 1).toLocaleDateString("en-IN", {
    month: "long",
    year: "numeric",
  });
}
function daysInMonth(y, m) {
  return new Date(y, m + 1, 0).getDate();
}
function firstDayOfWeek(y, m) {
  let d = new Date(y, m, 1).getDay();
  return d === 0 ? 6 : d - 1; // Mon=0
}

// ════════════════════════════════════════
// SAMPLE DATA SEEDING
// ════════════════════════════════════════
function attSeed() {
  const staff = [
    {
      id: "SRT001",
      name: "Junaid Mansuri",
      dept: "Management",
      role: "Manager",
      salary: 0,
    },
    {
      id: "SRT002",
      name: "Amit Kumar",
      dept: "Finance",
      role: "Accountant",
      salary: 0,
    },
    {
      id: "SRT003",
      name: "Vikash Kumar",
      dept: "Operations",
      role: "Supervisor",
      salary: 0,
    },
    {
      id: "SRT004",
      name: "Maqsood Ali",
      dept: "HR",
      role: "HR Executive",
      salary: 0,
    },
    {
      id: "SRT005",
      name: "Nandini Gokhe",
      dept: "Admin",
      role: "Coordinator",
      salary: 0,
    },
    {
      id: "SRT006",
      name: "Arvind Jatav",
      dept: "Operations",
      role: "Driver",
      salary: 0,
    },
  ];
  const records = {};
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const curYear = today.getFullYear(),
    curMonth = today.getMonth();
  const rand = (arr) => arr[Math.floor(Math.random() * arr.length)];
  const statusPool = [
    "Present",
    "Present",
    "Present",
    "Present",
    "Present",
    "Present",
    "WFH",
    "Absent",
    "Late",
    "Half-Day",
  ];
  // Last 3 months dynamically
  const startMonth = Math.max(0, curMonth - 2);
  for (let mo = startMonth; mo <= curMonth; mo++) {
    const dim = daysInMonth(curYear, mo);
    for (let day = 1; day <= dim; day++) {
      const d = new Date(curYear, mo, day);
      d.setHours(0, 0, 0, 0);
      if (d > today) continue;
      const key = `${curYear}-${String(mo + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      records[key] = {};
      staff.forEach((st) => {
        const status = rand(statusPool);
        const note =
          NOTE_OPTS[status] && Math.random() > 0.5
            ? rand(NOTE_OPTS[status])
            : "";
        records[key][st.id] = { status, note };
      });
    }
  }
  return { staff, records };
}

// ════════════════════════════════════════
// PERSISTENCE
// ════════════════════════════════════════
function attLoad() {
  try {
    const staff = JSON.parse(localStorage.getItem(SK.STAFF));
    const records = JSON.parse(localStorage.getItem(SK.RECORDS));
    const holidays = JSON.parse(localStorage.getItem(SK.HOLIDAYS) || "{}");
    if (staff && staff.length && records) {
      ATT.staff = staff.map((s) => ({ ...s, salary: Number(s.salary) || 0 }));
      ATT.records = records;
      ATT.holidays = holidays || {};
    } else {
      const d = attSeed();
      ATT.staff = d.staff;
      ATT.records = d.records;
      ATT.holidays = {};
      attPersist();
    }
  } catch (e) {
    const d = attSeed();
    ATT.staff = d.staff;
    ATT.records = d.records;
  }
  // Ensure today has records if staff exist but today has no data
  const td = todayStr();
  if (
    ATT.staff.length &&
    !ATT.records[td] &&
    localStorage.getItem(SK.CLEARED) !== "1"
  ) {
    const statPool = [
      "Present",
      "Present",
      "Present",
      "Present",
      "Present",
      "WFH",
      "Absent",
      "Late",
    ];
    ATT.records[td] = {};
    ATT.staff.forEach((st) => {
      ATT.records[td][st.id] = {
        status: statPool[Math.floor(Math.random() * statPool.length)],
        note: "",
      };
    });
    attPersist();
  }
  ATT.calStaffId = ATT.staff[0]?.id || null;
  ATT.salaryStaffId = ATT.staff[0]?.id || null;
}
function attPersist() {
  try {
    localStorage.setItem(SK.STAFF, JSON.stringify(ATT.staff));
    localStorage.setItem(SK.RECORDS, JSON.stringify(ATT.records));
    localStorage.setItem(SK.HOLIDAYS, JSON.stringify(ATT.holidays || {}));
  } catch (e) {}
}

// ════════════════════════════════════════
// TOAST
// ════════════════════════════════════════
// toast() uses dashboard's global toast function

// ════════════════════════════════════════
// NAVIGATION / DATE
// ════════════════════════════════════════
function attTab(id, btn) {
  ATT.tab = id;
  document
    .querySelectorAll(".att-tab-btn")
    .forEach((b) => b.classList.remove("active"));
  btn.classList.add("active");
  document
    .querySelectorAll(".att-tab-pane")
    .forEach((t) => t.classList.remove("active"));
  document.getElementById("att-tab-" + id).classList.add("active");
  if (id === "calendar") attCalRender();
  if (id === "staff") attListRender();
  if (id === "salary") attSalaryRender();
}

function attDateChange(val) {
  ATT.date = val;
  attStats();
  attTableRender();
  document.getElementById("attDateLabel").textContent = fmtDate(val);
  document.getElementById("printDate").textContent = "Date: " + fmtDate(val);
  attUpdateHolidayButton();
}
function attShiftDate(d) {
  const dt = new Date(ATT.date + "T00:00:00");
  dt.setDate(dt.getDate() + d);
  const s = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
  document.getElementById("dateInput").value = s;
  attDateChange(s);
}

// ════════════════════════════════════════
// STATS
// ════════════════════════════════════════
function getDayRecords() {
  return ATT.records[ATT.date] || {};
}
function attStats() {
  const rec = getDayRecords();
  const total = ATT.staff.length;
  const counts = {
    Present: 0,
    WFH: 0,
    Absent: 0,
    Late: 0,
    "Half-Day": 0,
    unmarked: 0,
  };
  ATT.staff.forEach((st) => {
    const r = rec[st.id];
    if (r?.status) counts[r.status] = (counts[r.status] || 0) + 1;
    else counts.unmarked++;
  });
  document.getElementById("sc-total").textContent = total;
  document.getElementById("sc-present").textContent = counts.Present;
  document.getElementById("sc-wfh").textContent = counts.WFH;
  document.getElementById("sc-absent").textContent = counts.Absent;
  document.getElementById("sc-late").textContent = counts.Late;
  document.getElementById("sc-half").textContent = counts["Half-Day"];
  const pct = total
    ? Math.round(
        ((counts.Present +
          counts.WFH +
          counts.Late +
          counts["Half-Day"] * 0.5) /
          total) *
          100,
      )
    : 0;
  document.getElementById("sc-present-pct").textContent = total
    ? `${Math.round((counts.Present / total) * 100)}% of staff`
    : "";
  document.getElementById("sc-wfh-pct").textContent = total
    ? `${Math.round((counts.WFH / total) * 100)}% of staff`
    : "";
  document.getElementById("sc-absent-pct").textContent = total
    ? `${Math.round((counts.Absent / total) * 100)}% of staff`
    : "";
  document.getElementById("sc-late-pct").textContent = total
    ? `${Math.round((counts.Late / total) * 100)}% of staff`
    : "";
  document.getElementById("sc-half-pct").textContent = total
    ? `${counts["Half-Day"]} staff`
    : "";
  document.getElementById("progFill").style.width = pct + "%";
  document.getElementById("progLabel").textContent =
    `${pct}% attendance value today`;
}

// ════════════════════════════════════════
// ATTENDANCE TABLE
// ════════════════════════════════════════
function attTableRender() {
  const rec = getDayRecords();
  const tbody = document.getElementById("attBody");
  if (!ATT.staff.length) {
    tbody.innerHTML = `<tr><td colspan="5"><div class="empty-state"><div class="empty-icon">👥</div><div>No staff added yet. Click <strong>+ Add Staff</strong> to get started.</div></div></td></tr>`;
    return;
  }
  tbody.innerHTML = ATT.staff
    .map((st) => {
      const r = rec[st.id] || { status: "", note: "" };
      const statusBtns = STATUSES.map(
        (s) =>
          `<button class="status-btn ${r.status === s ? "active-" + s : ""}" title="Mark ${s}" aria-pressed="${r.status === s ? "true" : "false"}" onclick="attToggleStatus('${st.id}','${s}')">${STATUS_ICON[s]}</button>`,
      ).join("");
      return `<tr id="row-${st.id}">
      <td><div class="staff-name">${st.name}</div><div class="staff-meta">${st.id}</div></td>
      <td><span class="dept-badge">${st.dept}</span></td>
      <td style="font-size:.82rem;opacity:.75">${st.role}</td>
      <td><div class="status-btns" id="btns-${st.id}">${statusBtns}</div></td>
      <td><input class="note-input" type="text" placeholder="Add note…" value="${r.note || ""}" id="note-${st.id}" list="note-suggestions-${r.status}"></td>
    </tr>`;
    })
    .join("");
}
function attToggleStatus(staffId, status) {
  if (ATT.holidays?.[ATT.date]) {
    toast("Company Holiday is locked as paid Present", "var(--holiday)");
    return;
  }
  // Update in-memory (not saved yet)
  if (!ATT.records[ATT.date]) ATT.records[ATT.date] = {};
  const cur = ATT.records[ATT.date][staffId]?.status;
  const newStatus = cur === status ? "" : status;
  if (!ATT.records[ATT.date][staffId])
    ATT.records[ATT.date][staffId] = { status: "", note: "" };
  ATT.records[ATT.date][staffId].status = newStatus;
  // Re-render just the buttons for this row
  const container = document.getElementById("btns-" + staffId);
  if (container) {
    container.innerHTML = STATUSES.map(
      (s) =>
        `<button class="status-btn ${newStatus === s ? "active-" + s : ""}" title="Mark ${s}" aria-pressed="${newStatus === s ? "true" : "false"}" onclick="attToggleStatus('${staffId}','${s}')">${STATUS_ICON[s]}</button>`,
    ).join("");
  }
  attStats();
}
function attMarkAll() {
  if (!ATT.records[ATT.date]) ATT.records[ATT.date] = {};
  ATT.staff.forEach((st) => {
    if (!ATT.records[ATT.date][st.id])
      ATT.records[ATT.date][st.id] = { status: "Present", note: "" };
    else ATT.records[ATT.date][st.id].status = "Present";
  });
  attTableRender();
  attStats();
  toast("All staff marked as Present", "var(--present)");
}
function attUpdateHolidayButton() {
  const btn = document.getElementById("companyHolidayBtn");
  const note = document.getElementById("attHolidayNote");
  if (!btn || !note) return;
  const active = !!ATT.holidays?.[ATT.date];
  btn.classList.toggle("active", active);
  btn.textContent = active
    ? "★ Company Holiday — Click to Remove"
    : "★ Mark Company Holiday";
  note.classList.toggle("show", active);
}
function attToggleCompanyHoliday() {
  if (!ATT.holidays) ATT.holidays = {};
  const wasHoliday = !!ATT.holidays[ATT.date];
  if (wasHoliday) {
    delete ATT.holidays[ATT.date];
    const day = ATT.records[ATT.date] || {};
    ATT.staff.forEach((st) => {
      const r = day[st.id];
      if (r && r.status === "Present" && r.note === "Company Holiday")
        delete day[st.id];
    });
    toast("Company Holiday removed for " + fmtDate(ATT.date), "var(--holiday)");
  } else {
    ATT.holidays[ATT.date] = { name: "Company Holiday" };
    if (!ATT.records[ATT.date]) ATT.records[ATT.date] = {};
    ATT.staff.forEach((st) => {
      ATT.records[ATT.date][st.id] = {
        status: "Present",
        note: "Company Holiday",
      };
    });
    toast(
      "★ Company Holiday marked · all employees set to Present",
      "var(--holiday)",
    );
  }
  attPersist();
  attTableRender();
  attStats();
  attUpdateHolidayButton();
  if (ATT.tab === "calendar") attCalRender();
  if (ATT.tab === "salary") attSalaryRender();
}

function attSave() {
  if (!ATT.records[ATT.date]) ATT.records[ATT.date] = {};
  ATT.staff.forEach((st) => {
    const noteEl = document.getElementById("note-" + st.id);
    if (!ATT.records[ATT.date][st.id])
      ATT.records[ATT.date][st.id] = { status: "", note: "" };
    if (noteEl) ATT.records[ATT.date][st.id].note = noteEl.value.trim();
  });
  attPersist();
  localStorage.removeItem(SK.CLEARED);
  attStats();
  attTableRender();
  toast("✅ Attendance saved for " + fmtDate(ATT.date), "var(--present)");
}

function attClearHistory() {
  if (!isUserAdmin()) {
    toast(
      "❌ Admin only: Only administrators can clear attendance history",
      "var(--red)",
    );
    return;
  }
  if (
    !window.confirm(
      "Clear all attendance history and company holidays? Staff records will remain.",
    )
  )
    return;
  ATT.records = {};
  ATT.holidays = {};
  localStorage.setItem(SK.CLEARED, "1");
  attPersist();
  attTableRender();
  attStats();
  attUpdateHolidayButton();
  if (ATT.tab === "calendar") attCalRender();
  if (ATT.tab === "salary") attSalaryRender();
  toast("Attendance history cleared", "var(--red)");
}

// ════════════════════════════════════════
// STAFF LIST
// ════════════════════════════════════════
function attListRender() {
  // Populate department filter
  const sel = document.querySelector(".att-dept-filter");
  if (sel.options.length <= 1) {
    DEPTS.forEach((d) => {
      const o = document.createElement("option");
      o.value = d;
      o.textContent = d;
      sel.appendChild(o);
    });
  }
  let list = ATT.staff;
  if (ATT.staffQ)
    list = list.filter(
      (s) =>
        s.name.toLowerCase().includes(ATT.staffQ) ||
        s.id.toLowerCase().includes(ATT.staffQ),
    );
  if (ATT.deptQ) list = list.filter((s) => s.dept === ATT.deptQ);
  document.getElementById("staffCount").textContent =
    `${list.length} of ${ATT.staff.length} staff`;
  const tbody = document.getElementById("staffBody");
  if (!list.length) {
    tbody.innerHTML = `<tr><td colspan="8"><div class="empty-state"><div class="empty-icon">${ATT.staff.length ? "🔍" : "👥"}</div><div>${ATT.staff.length ? "No staff match your filter." : "No staff added yet."}</div></div></td></tr>`;
    return;
  }
  tbody.innerHTML = list
    .map((st) => {
      // Count present/absent across all records
      let pCount = 0,
        aCount = 0,
        total = 0;
      Object.values(ATT.records).forEach((dayRec) => {
        const r = dayRec[st.id];
        if (!r) return;
        total++;
        if (r.status === "Present") pCount++;
        if (r.status === "Absent") aCount++;
      });
      return `<tr>
      <td><span class="mono" style="color:var(--cyan);font-family:monospace;font-size:.8rem">${st.id}</span></td>
      <td style="font-weight:600">${st.name}</td>
      <td><span class="dept-badge">${st.dept}</span></td>
      <td style="font-size:.82rem;opacity:.75">${st.role}</td>
      <td><span class="salary-money">${Number(st.salary) > 0 ? attMoney(st.salary) : '<span class="salary-missing">Not set</span>'}</span></td>
      <td style="text-align:center;color:var(--present);font-weight:700">${pCount}</td>
      <td style="text-align:center;color:var(--absent);font-weight:700">${aCount}</td>
      <td style="text-align:center"><div style="display:flex;gap:.35rem;justify-content:center">
        <button class="act-btn act-edit icon-only" title="Edit" aria-label="Edit" onclick="askAttendanceEdit('${st.id}')">✏️</button>
        ${isUserAdmin() ? `<button class="act-btn act-del icon-only" title="Delete" aria-label="Delete" onclick="attAskDel('${st.id}')">🗑️</button>` : `<button class="act-btn act-del icon-only" title="Delete (Admin only)" disabled style="opacity:0.5;cursor:not-allowed">🗑️</button>`}
      </div></td>
    </tr>`;
    })
    .join("");
}
function attSearch(q) {
  ATT.staffQ = q.toLowerCase();
  attListRender();
}
function attDeptFilter(q) {
  ATT.deptQ = q;
  attListRender();
}

// ════════════════════════════════════════
// STAFF MODAL
// ════════════════════════════════════════
function attStaffModal(id) {
  ATT.editId = id;
  document.getElementById("staffModalTitle").textContent = id
    ? "Edit Staff Member"
    : "Add Staff Member";
  if (id) {
    const st = ATT.staff.find((s) => s.id === id);
    document.getElementById("mf-name").value = st.name;
    document.getElementById("mf-id").value = st.id;
    document.getElementById("mf-dept").value = st.dept;
    document.getElementById("mf-role").value = st.role;
    document.getElementById("mf-salary").value = Number(st.salary) || "";
  } else {
    document.getElementById("mf-name").value = "";
    document.getElementById("mf-id").value = "";
    document.getElementById("mf-dept").value = "";
    document.getElementById("mf-role").value = "";
    document.getElementById("mf-salary").value = "";
  }
  document.getElementById("attStaffOverlay").classList.add("open");
  document.getElementById("mf-name").focus();
}
function askAttendanceEdit(id) {
  openRecordAuthorization("edit", () => attStaffModal(id));
}
function attCloseStaff() {
  document.getElementById("attStaffOverlay").classList.remove("open");
}

function attAutoId() {
  const max = ATT.staff.reduce((m, s) => {
    const n = parseInt(s.id.replace(/\D/g, ""));
    return n > m ? n : m;
  }, 0);
  document.getElementById("mf-id").value =
    "SRT" + String(max + 1).padStart(3, "0");
}

function attSaveStaff() {
  const name = document.getElementById("mf-name").value.trim();
  const dept = document.getElementById("mf-dept").value;
  const role = document.getElementById("mf-role").value.trim();
  const salary = Number(document.getElementById("mf-salary").value);
  let id = document.getElementById("mf-id").value.trim().toUpperCase();
  if (!name) {
    toast("Please enter staff name", "var(--absent)");
    return;
  }
  if (!dept) {
    toast("Please select a department", "var(--absent)");
    return;
  }
  if (!role) {
    toast("Please enter designation/role", "var(--absent)");
    return;
  }
  if (!Number.isFinite(salary) || salary <= 0) {
    toast("Please enter a valid monthly salary", "var(--absent)");
    return;
  }
  if (!id) {
    const max = ATT.staff.reduce((m, s) => {
      const n = parseInt(s.id.replace(/\D/g, ""));
      return n > m ? n : m;
    }, 0);
    id = "SRT" + String(max + 1).padStart(3, "0");
  }
  if (ATT.editId) {
    const idx = ATT.staff.findIndex((s) => s.id === ATT.editId);
    if (idx >= 0)
      ATT.staff[idx] = { ...ATT.staff[idx], id, name, dept, role, salary };
  } else {
    if (ATT.staff.find((s) => s.id === id)) {
      toast("Staff ID already exists", "var(--absent)");
      return;
    }
    ATT.staff.push({ id, name, dept, role, salary });
  }
  attPersist();
  attCloseStaff();
  attStats();
  attTableRender();
  attListRender();
  // Update cal staff selector
  attCalPop();
  if (ATT.tab === "salary") attSalaryRender();
  toast(
    ATT.editId ? "✅ Staff updated" : "✅ Staff added successfully",
    "var(--present)",
  );
}

// ════════════════════════════════════════
// DELETE STAFF
// ════════════════════════════════════════
function attAskDel(id) {
  if (!isUserAdmin()) {
    toast(
      "❌ Admin only: Only administrators can delete records",
      "var(--red)",
    );
    return;
  }
  openRecordAuthorization("delete", () => {
    ATT.delId = id;
    const st = ATT.staff.find((s) => s.id === id);
    document.getElementById("delMsg").textContent =
      `Remove "${st?.name}"? All attendance records for this person will also be deleted.`;
    document.getElementById("attDelOverlay").classList.add("open");
  });
}
function attCloseDel() {
  document.getElementById("attDelOverlay").classList.remove("open");
  ATT.delId = null;
}
function attConfirmDel() {
  if (!ATT.delId) return;
  ATT.staff = ATT.staff.filter((s) => s.id !== ATT.delId);
  Object.keys(ATT.records).forEach((date) => {
    if (ATT.records[date][ATT.delId]) delete ATT.records[date][ATT.delId];
  });
  attPersist();
  attCloseDel();
  attStats();
  attTableRender();
  attListRender();
  attCalPop();
  toast("Staff member removed", "var(--absent)");
}

// ════════════════════════════════════════
// CALENDAR
// ════════════════════════════════════════
function attCalPop() {
  const sel = document.getElementById("calStaffSelect");
  sel.innerHTML = ATT.staff
    .map(
      (st) =>
        `<option value="${st.id}" ${ATT.calStaffId === st.id ? "selected" : ""}>${st.name} (${st.id})</option>`,
    )
    .join("");
  if (!ATT.calStaffId && ATT.staff.length) ATT.calStaffId = ATT.staff[0].id;
}
function attCalStaff(id) {
  ATT.calStaffId = id;
  attCalRender();
}
function attCalShift(d) {
  ATT.calMonth += d;
  if (ATT.calMonth < 0) {
    ATT.calMonth = 11;
    ATT.calYear--;
  }
  if (ATT.calMonth > 11) {
    ATT.calMonth = 0;
    ATT.calYear++;
  }
  attCalRender();
}

function attCalRender() {
  attCalPop();
  const y = ATT.calYear,
    m = ATT.calMonth;
  document.getElementById("calMonthLabel").textContent = fmtMonthYear(y, m);
  const st = ATT.staff.find((s) => s.id === ATT.calStaffId);
  if (!st || !ATT.calStaffId) {
    document.getElementById("calGrid").innerHTML =
      '<div style="padding:2rem;opacity:.4;grid-column:1/-1">No staff selected.</div>';
    return;
  }

  // Compute monthly stats for this staff
  const dim = daysInMonth(y, m);
  const counts = { Present: 0, WFH: 0, Absent: 0, Late: 0, "Half-Day": 0 };
  for (let day = 1; day <= dim; day++) {
    const key = `${y}-${String(m + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    const rec = ATT.records[key]?.[ATT.calStaffId];
    if (rec?.status) counts[rec.status] = (counts[rec.status] || 0) + 1;
  }
  document.getElementById("calStats").innerHTML = [
    { l: "Present", c: "var(--present)", v: counts.Present },
    { l: "WFH", c: "var(--wfh)", v: counts.WFH },
    { l: "Absent", c: "var(--absent)", v: counts.Absent },
    { l: "Late", c: "var(--late)", v: counts.Late },
    { l: "Half-Day", c: "var(--half)", v: counts["Half-Day"] },
  ]
    .map(
      (i) =>
        `<div class="cal-stat"><span class="cal-stat-dot" style="background:${i.c}"></span>${i.l}: <strong>${i.v}</strong></div>`,
    )
    .join("");

  const firstDow = firstDayOfWeek(y, m); // 0=Mon
  const todayStr_ = todayStr();
  let cells = "";
  // Empty cells before first day
  for (let i = 0; i < firstDow; i++)
    cells += `<div class="cal-cell empty"></div>`;
  for (let day = 1; day <= dim; day++) {
    const key = `${y}-${String(m + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    const rec = ATT.records[key]?.[ATT.calStaffId];
    const status = rec?.status || "";
    const note = rec?.note || "";
    const dow = new Date(y, m, day).getDay(); // 0=Sun, 6=Sat
    const isWeekend = dow === 0 || dow === 6;
    const isSunday = dow === 0;
    const isHoliday = !!ATT.holidays?.[key];
    const isToday = key === todayStr_;
    const pillClass = status ? `cal-status-pill status-pill-${status}` : "";
    const pillText = status ? STATUS_ICON[status] : "";
    cells += `<div class="cal-cell${isWeekend ? " weekend" : ""}${isToday ? " today" : ""}" onclick="attDayDetail('${key}','${ATT.calStaffId}')">
      <div class="cal-day-num">${day}</div>
      ${isHoliday ? `<div class="cal-paid-off">★ Company Holiday</div>` : isSunday ? `<div class="cal-paid-sunday">Paid Sunday</div>` : pillClass ? `<div class="${pillClass}">${pillText}</div>` : ""}
      ${note && !isHoliday ? `<div class="cal-note">${note}</div>` : ""}
    </div>`;
  }
  document.getElementById("calGrid").innerHTML = cells;
}

// Day detail popup
function attDayDetail(dateKey, staffId) {
  const st = ATT.staff.find((s) => s.id === staffId);
  const rec = ATT.records[dateKey]?.[staffId];
  const d = new Date(dateKey + "T00:00:00");
  document.getElementById("dayModalTitle").textContent =
    `${st?.name} — ${d.toLocaleDateString("en-IN", { weekday: "long", day: "numeric", month: "long", year: "numeric" })}`;
  if (rec?.status) {
    const color = STATUS_COLOR[rec.status],
      bg = STATUS_BG[rec.status];
    document.getElementById("dayStatusBadge").innerHTML =
      `<span class="status-badge" style="background:${bg};color:${color};border:1px solid ${color}20">${STATUS_ICON[rec.status]}</span>`;
    document.getElementById("dayNoteText").textContent =
      rec.note || "No notes recorded.";
  } else {
    document.getElementById("dayStatusBadge").innerHTML =
      `<span class="status-badge" style="background:rgba(255,255,255,.07);color:rgba(255,255,255,.4)">No record</span>`;
    document.getElementById("dayNoteText").textContent =
      "No attendance marked for this day.";
  }
  document.getElementById("attDayOverlay").classList.add("open");
}
function attCloseDay() {
  document.getElementById("attDayOverlay").classList.remove("open");
}

