// ════════════════════════════════════════
// GPS RECORD MANAGEMENT SYSTEM
// ════════════════════════════════════════

// ════════════════════════════════════════
// GPS RECORD MANAGEMENT SYSTEM
// ════════════════════════════════════════
const GPS_SK = "srt_gps_records_v1";
const GPS_FIELDS = [
  "gpsId",
  "dateIssued",
  "vehicleNumber",
  "gpsType",
  "gpsAmount",
  "gpsReturn",
  "returnDate",
  "amountReturn",
  "lateFee",
  "balanceDue",
  "owner",
  "remark",
];

let GPS_PAGE = 1;
const GPS_PAGE_SIZE = 20;
let GPSD = {
  records: [],
  editId: null,
  delId: null,
  formOpen: false,
  sortCol: "dateIssued",
  sortDir: "desc",
  filteredIds: null,
  newId: null,
};

// ── HELPERS ──
function gpsUid() {
  return "g" + Date.now() + Math.random().toString(36).slice(2, 6);
}
function gpsInr(n) {
  n = parseFloat(n) || 0;
  if (n === 0) return "—";
  if (n >= 100000) return "₹" + (n / 100000).toFixed(1) + "L";
  if (n >= 1000) return "₹" + n.toLocaleString("en-IN");
  return "₹" + n;
}
function gpsFmtDate(s) {
  if (!s) return "—";
  const d = new Date(s + "T00:00:00");
  return d.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}
function gpsSV(v) {
  return v === undefined || v === null || String(v).trim() === ""
    ? ""
    : String(v);
}
function gpsFlashCard(id) {
  const e = document.getElementById(id);
  if (!e) return;
  e.classList.remove("flash");
  void e.offsetWidth;
  e.classList.add("flash");
}

// ── PERSISTENCE ──
function gpsLoad() {
  try {
    const storedValue = localStorage.getItem(GPS_SK);
    const stored = storedValue === null ? null : JSON.parse(storedValue);
    if (Array.isArray(stored)) {
      GPSD.records = stored;
    } else {
      GPSD.records = gpsSampleData();
      gpsPersist();
    }
  } catch (e) {
    GPSD.records = gpsSampleData();
  }
}
function gpsPersist() {
  try {
    localStorage.setItem(GPS_SK, JSON.stringify(GPSD.records));
  } catch (e) {}
}

