// ── FORM TOGGLE ──
function gpsToggleForm(forceOpen) {
  const panel = document.getElementById("gpsFormPanel");
  const icon = document.getElementById("gpsFormToggleIcon");
  const label = document.getElementById("gpsFormToggleLabel");
  GPSD.formOpen = forceOpen !== undefined ? forceOpen : !GPSD.formOpen;
  if (GPSD.formOpen) {
    panel.classList.remove("collapsed");
    panel.style.maxHeight = "900px";
    icon.textContent = "✕";
    label.textContent = "Close Form";
  } else {
    panel.style.maxHeight = "0";
    setTimeout(() => panel.classList.add("collapsed"), 350);
    icon.textContent = "＋";
    label.textContent = "Add Record";
    GPSD.editId = null;
    document.getElementById("gpsFormTitle").textContent = "Add GPS Record";
    document.getElementById("gpsFormBadge").textContent = "NEW RECORD";
  }
}

// ── RETURN TOGGLE ──
function gpsReturnToggle(val) {
  const yes = val === "Yes";
  ["gf-returnDate", "gf-amountReturn"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) {
      el.disabled = !yes;
      if (!yes) el.value = "";
    }
  });
}

// ── RESET FORM ──
function gpsResetForm() {
  GPS_FIELDS.forEach((k) => {
    const el = document.getElementById("gf-" + k);
    if (el) el.value = k === "gpsReturn" ? "No" : "";
  });
  document.getElementById("gf-dateIssued").value = new Date()
    .toISOString()
    .slice(0, 10);
  gpsReturnToggle("No");
  GPSD.editId = null;
  document.getElementById("gpsFormTitle").textContent = "Add GPS Record";
  document.getElementById("gpsFormBadge").textContent = "NEW RECORD";
}

// ── POPULATE FORM ──
function gpsPopulateForm(rec) {
  GPS_FIELDS.forEach((k) => {
    const el = document.getElementById("gf-" + k);
    if (el) el.value = gpsSV(rec[k]);
  });
  gpsReturnToggle(gpsSV(rec.gpsReturn) || "No");
}

// ── SAVE RECORD ──
function gpsSaveRecord() {
  const gpsId = document.getElementById("gf-gpsId").value.trim();
  const dateIssued = document.getElementById("gf-dateIssued").value;
  const vehicleNumber = document
    .getElementById("gf-vehicleNumber")
    .value.trim();
  const gpsType = document.getElementById("gf-gpsType").value;
  if (!gpsId) {
    toast("GPS ID is required", "var(--absent)");
    return;
  }
  if (!dateIssued) {
    toast("Date Issued is required", "var(--absent)");
    return;
  }
  if (!vehicleNumber) {
    toast("Vehicle Number is required", "var(--absent)");
    return;
  }
  if (!gpsType) {
    toast("GPS Type is required", "var(--absent)");
    return;
  }

  const rec = {
    id: GPSD.editId || gpsUid(),
    gpsId,
    dateIssued,
    vehicleNumber,
    gpsType,
    gpsAmount: parseFloat(document.getElementById("gf-gpsAmount").value) || 0,
    gpsReturn: document.getElementById("gf-gpsReturn").value || "No",
    returnDate: document.getElementById("gf-returnDate").value || "",
    amountReturn:
      parseFloat(document.getElementById("gf-amountReturn").value) || 0,
    lateFee: parseFloat(document.getElementById("gf-lateFee").value) || 0,
    balanceDue: parseFloat(document.getElementById("gf-balanceDue").value) || 0,
    owner: document.getElementById("gf-owner").value.trim(),
    remark: document.getElementById("gf-remark").value.trim(),
  };

  if (GPSD.editId) {
    const idx = GPSD.records.findIndex((r) => r.id === GPSD.editId);
    if (idx >= 0) GPSD.records[idx] = rec;
    toast("✅ GPS record updated", "var(--green)");
  } else {
    GPSD.records.unshift(rec);
    GPSD.newId = rec.id;
    toast("✅ GPS record added", "var(--green)");
  }

  gpsPersist();
  gpsResetForm();
  gpsToggleForm(false);
  gpsApplyFilters();
  gpsRenderStats();
  gpsUpdateDashKPI();
  [
    "gsc-devices",
    "gsc-charged",
    "gsc-returned",
    "gsc-late",
    "gsc-balance",
    "gsc-pending",
  ].forEach(gpsFlashCard);
  setTimeout(() => (GPSD.newId = null), 2000);
}

// ── EDIT ──
function gpsEdit(id) {
  openRecordAuthorization("edit", () => gpsEditAuthorized(id));
}
function gpsEditAuthorized(id) {
  const rec = GPSD.records.find((r) => r.id === id);
  if (!rec) return;
  GPSD.editId = id;
  gpsPopulateForm(rec);
  document.getElementById("gpsFormTitle").textContent = "Edit GPS Record";
  document.getElementById("gpsFormBadge").textContent = "EDIT MODE";
  gpsToggleForm(true);
  document
    .getElementById("gpsFormPanel")
    .scrollIntoView({ behavior: "smooth", block: "nearest" });
}

// ── DELETE ──
function gpsAskDel(id) {
  if (!isUserAdmin()) {
    toast(
      "❌ Admin only: Only administrators can delete records",
      "var(--red)",
    );
    return;
  }
  openRecordAuthorization("delete", () => {
    GPSD.delId = id;
    const rec = GPSD.records.find((r) => r.id === id);
    document.getElementById("gpsDelMsg").textContent =
      `Delete GPS record for vehicle "${rec?.vehicleNumber || id}"? This cannot be undone.`;
    document.getElementById("gpsDelOverlay").classList.add("open");
  });
}
function gpsCloseDel() {
  document.getElementById("gpsDelOverlay").classList.remove("open");
  GPSD.delId = null;
}
function gpsConfirmDel() {
  if (!GPSD.delId) return;
  GPSD.records = GPSD.records.filter((r) => r.id !== GPSD.delId);
  gpsPersist();
  gpsCloseDel();
  gpsApplyFilters();
  gpsRenderStats();
  gpsUpdateDashKPI();
  toast("🗑 GPS record deleted", "var(--red)");
}

// ── CLEAR ALL ──
function gpsConfirmClearAll() {
  document.getElementById("gpsClearOverlay").classList.add("open");
  document.getElementById("gpsIEMenu").classList.remove("open");
}
function gpsCloseClear() {
  document.getElementById("gpsClearOverlay").classList.remove("open");
}
function gpsClearAll() {
  GPSD.records = [];
  gpsPersist();
  gpsCloseClear();
  gpsApplyFilters();
  gpsRenderStats();
  gpsUpdateDashKPI();
  toast("All GPS records cleared", "var(--red)");
}

// ── SORT ──
function gpsSort(col) {
  if (GPSD.sortCol === col) {
    GPSD.sortDir = GPSD.sortDir === "asc" ? "desc" : "asc";
  } else {
    GPSD.sortCol = col;
    GPSD.sortDir = "asc";
  }
  // Update header classes
  document.querySelectorAll(".gps-table thead th").forEach((th) => {
    th.classList.remove("sort-asc", "sort-desc");
    if (
      th.textContent.toLowerCase().includes(
        col
          .toLowerCase()
          .replace(/([A-Z])/g, " $1")
          .trim()
          .toLowerCase(),
      ) ||
      th.getAttribute("onclick") === "gpsSort('" + col + "')"
    ) {
      th.classList.add("sort-" + GPSD.sortDir);
    }
  });
  gpsApplyFilters();
}

// ── FILTER + RENDER TABLE ──
function gpsApplyFilters(resetPage = true) {
  const q = document.getElementById("gpsSearch")?.value?.toLowerCase() || "";
  const fromD = document.getElementById("gpsFromDate")?.value || "";
  const toD = document.getElementById("gpsToDate")?.value || "";
  const typeF = document.getElementById("gpsTypeFilter")?.value || "";
  const retF = document.getElementById("gpsReturnFilter")?.value || "";

  let rows = [...GPSD.records];

  // Search filter
  if (q)
    rows = rows.filter((r) =>
      (r.gpsId + r.vehicleNumber + r.gpsType + r.owner + r.remark)
        .toLowerCase()
        .includes(q),
    );
  // Date range
  if (fromD) rows = rows.filter((r) => r.dateIssued >= fromD);
  if (toD) rows = rows.filter((r) => r.dateIssued <= toD);
  // Type filter
  if (typeF) rows = rows.filter((r) => r.gpsType === typeF);
  // Return filter
  if (retF) rows = rows.filter((r) => r.gpsReturn === retF);

  // Descending by default: latest date / record first.
  const col = GPSD.sortCol;
  rows.sort((a, b) => {
    const av = a[col] || "",
      bv = b[col] || "";
    const an = parseFloat(av),
      bn = parseFloat(bv);
    const cmp =
      !isNaN(an) && !isNaN(bn) ? an - bn : String(av).localeCompare(String(bv));
    return GPSD.sortDir === "asc" ? cmp : -cmp;
  });

  GPSD.filteredIds = rows.map((r) => r.id); // keep all filtered rows for export
  if (resetPage) GPS_PAGE = 1;
  const totalPages = Math.max(1, Math.ceil(rows.length / GPS_PAGE_SIZE));
  GPS_PAGE = Math.min(Math.max(GPS_PAGE, 1), totalPages);
  const startRow = (GPS_PAGE - 1) * GPS_PAGE_SIZE;
  const pageRows = rows.slice(startRow, startRow + GPS_PAGE_SIZE);
  gpsRenderTable(pageRows, startRow);
  const cnt = document.getElementById("gpsTblCnt");
  if (cnt) {
    if (!rows.length) cnt.textContent = `0 of ${GPSD.records.length} records`;
    else {
      const from = startRow + 1,
        to = Math.min(startRow + pageRows.length, rows.length);
      cnt.textContent =
        rows.length === GPSD.records.length
          ? `${from}-${to} of ${GPSD.records.length} records`
          : `${from}-${to} of ${rows.length} filtered · ${GPSD.records.length} total`;
    }
  }
  const pager = document.getElementById("gpsPager");
  if (pager) {
    pager.innerHTML = `<button type="button" onclick="gpsChangePage(-1)" ${GPS_PAGE <= 1 ? "disabled" : ""}>← Previous</button><span class="page-info">Page ${GPS_PAGE} of ${totalPages}</span><button type="button" onclick="gpsChangePage(1)" ${GPS_PAGE >= totalPages ? "disabled" : ""}>Next →</button>`;
  }
  // Update sidebar badge
  const nb = document.getElementById("nb-gps");
  if (nb) nb.textContent = GPSD.records.length;
}
function gpsChangePage(delta) {
  GPS_PAGE += delta;
  gpsApplyFilters(false);
  document
    .getElementById("gpsTable")
    ?.closest(".gps-tbl-wrap")
    ?.scrollTo({ top: 0, left: 0, behavior: "auto" });
}

function gpsRenderTable(rows, startRow = 0) {
  const tbody = document.getElementById("gpsTBody");
  if (!tbody) return;
  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="14"><div class="gps-empty"><div class="gps-empty-icon">📡</div><div>${GPSD.records.length ? "No records match your filters." : "No GPS records yet. Click + Add Record to get started."}</div></div></td></tr>`;
    return;
  }
  tbody.innerHTML = rows
    .map((r, idx) => {
      const isNew = r.id === GPSD.newId;
      const retBadge =
        r.gpsReturn === "Yes"
          ? '<span class="gps-badge gps-badge-yes">✓ Returned</span>'
          : '<span class="gps-badge gps-badge-no">⏳ Pending</span>';
      const typeBadge = `<span class="gps-type-badge">${r.gpsType || "—"}</span>`;
      return `<tr class="${isNew ? "new-row" : ""}">
      <td style="opacity:.35;font-size:.75rem">${startRow + idx + 1}</td>
      <td><span class="gps-mono">${r.gpsId || "—"}</span></td>
      <td>${gpsFmtDate(r.dateIssued)}</td>
      <td><span class="gps-mono">${r.vehicleNumber || "—"}</span></td>
      <td>${typeBadge}</td>
      <td><span class="gps-amt gps-amt-charged">${r.gpsAmount ? gpsInr(r.gpsAmount) : "—"}</span></td>
      <td>${retBadge}</td>
      <td>${gpsFmtDate(r.returnDate)}</td>
      <td><span class="gps-amt gps-amt-returned">${r.amountReturn ? gpsInr(r.amountReturn) : "—"}</span></td>
      <td><span class="gps-amt gps-amt-late">${r.lateFee ? gpsInr(r.lateFee) : "—"}</span></td>
      <td><span class="gps-amt gps-amt-balance" style="${r.balanceDue > 0 ? "" : "opacity:.35"}">${r.balanceDue ? gpsInr(r.balanceDue) : "—"}</span></td>
      <td style="font-size:.78rem;opacity:.65;max-width:100px;overflow:hidden;text-overflow:ellipsis">${r.owner || "—"}</td>
      <td><span class="gps-remark" title="${r.remark || ""}">${r.remark || "—"}</span></td>
      <td class="gps-act-col" style="text-align:center" data-gps-action>
        <div style="display:flex;gap:.3rem;justify-content:center;">
          <button class="gps-btn gps-btn-cyan gps-btn-sm icon-only" title="Edit" aria-label="Edit" onclick="gpsEdit('${r.id}')">✏️</button>
          ${isUserAdmin() ? `<button class="gps-btn gps-btn-red gps-btn-sm icon-only" title="Delete" aria-label="Delete" onclick="gpsAskDel('${r.id}')">🗑️</button>` : `<button class="gps-btn gps-btn-red gps-btn-sm icon-only" title="Delete (Admin only)" disabled style="opacity:0.5;cursor:not-allowed">🗑️</button>`}
        </div>
      </td>
    </tr>`;
    })
    .join("");
}

// ── STATS ──
function gpsRenderStats() {
  const recs = GPSD.records;
  const total = recs.length;
  const charged = recs.reduce((s, r) => s + (r.gpsAmount || 0), 0);
  const returned = recs.reduce((s, r) => s + (r.amountReturn || 0), 0);
  const late = recs.reduce((s, r) => s + (r.lateFee || 0), 0);
  const balance = recs.reduce((s, r) => s + (r.balanceDue || 0), 0);
  const pending = recs.filter((r) => r.gpsReturn === "No").length;
  const set = (id, v) => {
    const e = document.getElementById(id);
    if (e) e.textContent = v;
  };
  set("gsc-v-devices", total);
  set("gsc-v-charged", total ? gpsInr(charged) : "₹0");
  set("gsc-v-returned", total ? gpsInr(returned) : "₹0");
  set("gsc-v-late", total ? gpsInr(late) : "₹0");
  set("gsc-v-balance", total ? gpsInr(balance) : "₹0");
  set("gsc-v-pending", pending);
  gpsRenderMonthly();
}

// ── UPDATE DASHBOARD KPI ──
function gpsUpdateDashKPI() {
  const nb = document.getElementById("nb-gps");
  if (nb) nb.textContent = GPSD.records.length;
  const kv = document.getElementById("k-gps");
  if (kv) kv.textContent = GPSD.records.length;
}

// ── CLEAR FILTERS ──
function gpsClearFilters() {
  ["gpsSearch", "gpsFromDate", "gpsToDate"].forEach((id) => {
    const e = document.getElementById(id);
    if (e) e.value = "";
  });
  ["gpsTypeFilter", "gpsReturnFilter"].forEach((id) => {
    const e = document.getElementById(id);
    if (e) e.value = "";
  });
  gpsApplyFilters();
}

// ── EXPORT ──
function gpsExportCSV() {
  gpsDoExport(GPSD.records, "SRT_GPS_All");
}
function gpsExportFiltered() {
  const rows = GPSD.filteredIds
    ? GPSD.records.filter((r) => GPSD.filteredIds.includes(r.id))
    : GPSD.records;
  gpsDoExport(rows, "SRT_GPS_Filtered");
}
function gpsDoExport(rows, name) {
  const headers = [
    "GPS ID",
    "Date Issued",
    "Vehicle Number",
    "GPS Type",
    "GPS Amount (₹)",
    "GPS Return",
    "Return Date",
    "Amount Return (₹)",
    "Late Fee (₹)",
    "Balance Due (₹)",
    "Owner",
    "Remark",
  ];
  const keys = [
    "gpsId",
    "dateIssued",
    "vehicleNumber",
    "gpsType",
    "gpsAmount",
    "gpsReturn",
    "returnDate",
    "amountReturn",
    "lateFee",
    "balanceDue",
    "owner",
    "remark",
  ];
  const csv = [
    headers.join(","),
    ...rows.map((r) =>
      keys.map((k) => `"${String(r[k] ?? "").replace(/"/g, '""')}"`).join(","),
    ),
  ].join("\n");
  const a = document.createElement("a");
  a.href = "data:text/csv;charset=utf-8," + encodeURIComponent(csv);
  a.download = `${name}_${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  toast("⬇ CSV exported", "var(--cyan)");
  document.getElementById("gpsIEMenu").classList.remove("open");
}

// ── IMPORT ──
function gpsImport(evt) {
  const file = evt.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      let imported = [];
      if (file.name.endsWith(".json")) {
        const parsed = JSON.parse(e.target.result);
        imported = Array.isArray(parsed) ? parsed : [parsed];
      } else {
        // CSV parse
        const lines = e.target.result.split("\n").filter((l) => l.trim());
        const headers = lines[0]
          .split(",")
          .map((h) => h.replace(/^"|"$/g, "").trim());
        const keyMap = {
          "GPS ID": "gpsId",
          "Date Issued": "dateIssued",
          "Vehicle Number": "vehicleNumber",
          "GPS Type": "gpsType",
          "GPS Amount (₹)": "gpsAmount",
          "GPS Return": "gpsReturn",
          "Return Date": "returnDate",
          "Amount Return (₹)": "amountReturn",
          "Late Fee (₹)": "lateFee",
          "Balance Due (₹)": "balanceDue",
          Owner: "owner",
          Remark: "remark",
        };
        imported = lines.slice(1).map((line) => {
          const vals = line.match(/(".*?"|[^,]+)(?=,|$)/g) || line.split(",");
          const rec = { id: gpsUid() };
          headers.forEach((h, i) => {
            const k = keyMap[h] || h;
            const v = (vals[i] || "").replace(/^"|"$/g, "").trim();
            rec[k] = [
              "gpsAmount",
              "amountReturn",
              "lateFee",
              "balanceDue",
            ].includes(k)
              ? parseFloat(v) || 0
              : v;
          });
          return rec;
        });
      }
      // Merge (skip duplicates by gpsId+dateIssued+vehicleNumber)
      let added = 0;
      imported.forEach((rec) => {
        const dup = GPSD.records.find(
          (r) =>
            r.gpsId === rec.gpsId &&
            r.dateIssued === rec.dateIssued &&
            r.vehicleNumber === rec.vehicleNumber,
        );
        if (!dup) {
          if (!rec.id) rec.id = gpsUid();
          GPSD.records.unshift(rec);
          added++;
        }
      });
      gpsPersist();
      gpsApplyFilters();
      gpsRenderStats();
      gpsUpdateDashKPI();
      toast(
        `✅ Imported ${added} new records (${imported.length - added} skipped as duplicates)`,
        "var(--green)",
      );
    } catch (err) {
      toast("Import failed: " + err.message, "var(--red)");
    }
    evt.target.value = "";
  };
  reader.readAsText(file);
  document.getElementById("gpsIEMenu").classList.remove("open");
}

// ── IE MENU TOGGLE ──
function gpsIEMenu() {
  srtToggleTransferMenu("gpsIEMenu");
}

// ── INIT GPS ──
function initGPS() {
  gpsLoad();
  // Set default date in form
  const di = document.getElementById("gf-dateIssued");
  if (di) di.value = new Date().toISOString().slice(0, 10);
  // Update dashboard home panel
  setTimeout(gpsUpdateHomePanel, 200);
  // Set print date
  const pd = document.getElementById("gpsPrintDate");
  if (pd) pd.textContent = "Generated: " + new Date().toLocaleString("en-IN");
  gpsRenderStats();
  gpsApplyFilters();
  gpsUpdateDashKPI();
}

// ── GPS scroll to records ──
function gpsScrollToRecords() {
  const tbl = document.querySelector(".gps-tbl-section");
  if (tbl) tbl.scrollIntoView({ behavior: "smooth", block: "start" });
  const body = document.querySelector(".gps-scroll-body");
  if (body) {
    setTimeout(
      () => body.scrollTo({ top: body.scrollHeight, behavior: "smooth" }),
      150,
    );
  }
}

// ── GPS Records counter on dashboard home ──
function gpsUpdateHomePanel() {
  const pending =
    typeof GPSD !== "undefined"
      ? GPSD.records.filter((r) => r.gpsReturn === "No").length
      : 0;
  const total = typeof GPSD !== "undefined" ? GPSD.records.length : 0;
  // Update the subtitle in the quick-access panel
  document.querySelectorAll(".ps").forEach((el) => {
    if (el.textContent.includes("pending returns")) {
      el.textContent = `Track device issuance · Returns · Payments · ${pending} pending returns (${total} total)`;
    }
  });
}

// ════════════════════════════════════════
// SIDEBAR TOGGLE — RESPONSIVE
// ════════════════════════════════════════
const SB_KEY = "srt_sb_state";

function isMobile() {
  return window.innerWidth <= 768;
}

function sidebarToggle() {
  const sb = document.querySelector(".sidebar");
  const btn = document.getElementById("menuToggle");
  if (isMobile()) {
    const isOpen = sb.classList.contains("mobile-open");
    if (isOpen) {
      sidebarClose();
    } else {
      sb.classList.add("mobile-open");
      document.getElementById("sbBackdrop").classList.add("visible");
      if (btn) btn.classList.add("is-open");
    }
  } else {
    const isMini = sb.classList.contains("mini");
    if (isMini) {
      sb.classList.remove("mini");
      localStorage.setItem(SB_KEY, "open");
    } else {
      sb.classList.add("mini");
      localStorage.setItem(SB_KEY, "mini");
    }
  }
}

function sidebarClose() {
  const sb = document.querySelector(".sidebar");
  const btn = document.getElementById("menuToggle");
  sb.classList.remove("mobile-open");
  document.getElementById("sbBackdrop")?.classList.remove("visible");
  if (btn) btn.classList.remove("is-open");
}

// Restore sidebar state on load
function restoreSidebar() {
  const saved = localStorage.getItem(SB_KEY);
  const sb = document.querySelector(".sidebar");
  if (!sb) return;
  if (!isMobile() && saved === "mini") {
    sb.classList.add("mini");
    // icon rotation handled by CSS transform
  }
}

// Close sidebar when nav item clicked on mobile
const origNav = typeof nav === "function" ? nav : null;
function nav(el) {
  document.querySelectorAll(".ni").forEach((n) => n.classList.remove("active"));
  el.classList.add("active");
  document.querySelectorAll(".cp").forEach((p) => p.classList.remove("active"));
  document.getElementById("cp-" + el.dataset.pg)?.classList.add("active");
  if (el.dataset.pg === "att") {
    if (typeof initAtt === "function") initAtt();
  }
  if (el.dataset.pg === "gps") {
    if (typeof initGPS === "function") initGPS();
  }
  // Close sidebar on mobile after navigation
  if (isMobile()) sidebarClose();
}

// Handle window resize
window.addEventListener("resize", () => {
  const sb = document.querySelector(".sidebar");
  if (!sb) return;
  if (!isMobile()) {
    // Remove mobile-open when resizing to desktop
    sb.classList.remove("mobile-open");
    document.getElementById("sbBackdrop")?.classList.remove("visible");
    document.getElementById("menuToggle")?.classList.remove("is-open");
    // Restore mini state
    const saved = localStorage.getItem(SB_KEY);
    if (saved === "mini" && !sb.classList.contains("mini")) {
      sb.classList.add("mini");
    }
  } else {
    // On mobile, remove mini class
    sb.classList.remove("mini");
  }
});

// Init after DOM ready
document.addEventListener("DOMContentLoaded", restoreSidebar);
document.addEventListener("DOMContentLoaded", moveFreightRateActionsToHeader);
// Also restore when dashboard becomes visible (after login)
const _origInitDash = typeof initDash === "function" ? initDash : null;

// ════════════════════════════════════════
// EXCEL EXPORT / IMPORT — All Pages
// ════════════════════════════════════════

// ── Dropdown toggle ──
function toggleXport(sheet) {
  srtToggleTransferMenu("xm-" + sheet);
}
function closeXport() {
  srtCloseTransferMenu();
}

// ── Export Excel (.xlsx) ──
function exportExcel(sheet) {
  if (typeof XLSX === "undefined") {
    toast("⚠ Excel library not loaded. Try Export CSV instead.", "var(--late)");
    return;
  }
  const rows = STATE[sheet];
  const cols = COLS[sheet];
  if (!rows || !rows.length) {
    toast("No data to export", "var(--absent)");
    return;
  }

  // Build array-of-arrays: header row + data rows
  const header = cols.map((c) => c.l);
  const data = rows.map((row) =>
    cols.map((c) => {
      const v = row[c.k];
      if (c.image)
        return typeof v === "string" && v.startsWith("data:image/")
          ? "Uploaded"
          : "Not Uploaded";
      // Try to keep numbers as numbers
      const n = parseFloat(v);
      return !isNaN(n) && String(v).trim() !== "" ? n : (v ?? "");
    }),
  );

  const ws = XLSX.utils.aoa_to_sheet([header, ...data]);

  // Column widths — auto-size based on max content
  const colWidths = header.map((h, ci) => {
    const maxLen = Math.max(
      h.length,
      ...data.map((r) => String(r[ci] ?? "").length),
    );
    return { wch: Math.min(Math.max(maxLen + 2, 10), 40) };
  });
  ws["!cols"] = colWidths;

  // Freeze header row
  ws["!freeze"] = {
    xSplit: 0,
    ySplit: 1,
    topLeftCell: "A2",
    activePane: "bottomLeft",
  };

  const wb = XLSX.utils.book_new();
  const sheetName =
    {
      inv: "Daily Entry",
      pay: "Payment",
      cp: "Company Payment",
      rp: "Received Payment",
      exp: "Expense",
      fr: "Freight Rates",
      trader: "Traders Details",
      vehicle: "Vehicle Details",
    }[sheet] || sheet.toUpperCase();
  XLSX.utils.book_append_sheet(wb, ws, sheetName);

  // Add metadata sheet
  const meta = XLSX.utils.aoa_to_sheet([
    ["Shree Ram Transport — Data Export"],
    ["Sheet", sheetName],
    ["Records", rows.length],
    ["Exported", new Date().toLocaleString("en-IN")],
    ["Generated by", "SRT Dashboard"],
  ]);
  XLSX.utils.book_append_sheet(wb, meta, "Info");

  const filename = `SRT_${sheetName.replace(/\s+/g, "_")}_${new Date().toISOString().slice(0, 10)}.xlsx`;
  XLSX.writeFile(wb, filename);
  toast(`📊 Exported ${rows.length} rows to Excel`, "var(--green)");
}

// ── Import Excel / CSV ──
function importExcel(sheet, inputEl) {
  const file = inputEl.files[0];
  if (!file) return;

  if (typeof XLSX === "undefined") {
    toast(
      "⚠ Excel library not loaded. Reload page and try again.",
      "var(--late)",
    );
    inputEl.value = "";
    return;
  }

  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const wb = XLSX.read(new Uint8Array(e.target.result), { type: "array" });
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rawData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: "" });

      if (!rawData || rawData.length < 2) {
        toast("⚠ File is empty or has no data rows", "var(--absent)");
        inputEl.value = "";
        return;
      }

      const fileHeaders = rawData[0].map((h) => String(h).trim());
      const cols = COLS[sheet];

      // Build column-key mapping: file header → internal key
      const colMap = {};
      fileHeaders.forEach((fh, fi) => {
        // Match by label (exact) or key (exact), case-insensitive
        const col = cols.find(
          (c) =>
            c.l.toLowerCase() === fh.toLowerCase() ||
            c.k.toLowerCase() === fh.toLowerCase(),
        );
        if (col && !col.image) colMap[fi] = col.k;
      });

      const mapped = rawData
        .slice(1)
        .filter((row) => row.some((cell) => String(cell).trim() !== ""))
        .map((row) => {
          const obj = {};
          Object.entries(colMap).forEach(([fi, key]) => {
            obj[key] = String(row[fi] ?? "").trim();
          });
          return obj;
        })
        .filter((obj) => Object.keys(obj).length > 0);

      if (!mapped.length) {
        toast(
          "⚠ No matching columns found. Check that headers match the export format.",
          "var(--late)",
        );
        inputEl.value = "";
        return;
      }

      // Merge: append new records, skip duplicates (based on first col key)
      const firstKey =
        sheet === "trader"
          ? "Trader Name"
          : sheet === "vehicle"
            ? "Vehicle Number"
            : cols[0]?.k;
      const existing = new Set(
        STATE[sheet].map((r) => String(r[firstKey] ?? "").toLowerCase()),
      );
      const toAdd = mapped.filter((r) => {
        const v = String(r[firstKey] ?? "").toLowerCase();
        return v && !existing.has(v);
      });
      const dupes = mapped.length - toAdd.length;

      STATE[sheet] = [...STATE[sheet], ...toAdd];
      if (sheet === "rp") {
        STATE.rp.forEach((r, i) => {
          r["Sr. No."] = String(i + 1);
          if (
            r["Received Date"] === undefined ||
            r["Received Date"] === null ||
            String(r["Received Date"]).trim() === ""
          )
            r["Received Date"] = "-";
          const a = parseFloat(r["Invoice Amount"]),
            b = parseFloat(r["Received Amount"]);
          r["Remaining Amount"] =
            !isNaN(a) && !isNaN(b)
              ? String(Math.round((a - b) * 100) / 100)
              : r["Remaining Amount"] || "-";
        });
        saveReceivedPaymentData();
      }
      if (sheet === "trader" || sheet === "vehicle") {
        STATE[sheet].forEach((r, i) => (r["Sr. No."] = String(i + 1)));
        saveFreightMasterData();
      }
      if (sheet === "fr") renderFr();
      else renderTable(sheet);
      updateKPIs(sheet);

      let msg = `✅ Imported ${toAdd.length} new records`;
      if (dupes > 0) msg += ` (${dupes} skipped as duplicates)`;
      toast(msg, "var(--green)");
    } catch (err) {
      toast("❌ Import failed: " + err.message, "var(--absent)");
      console.error("Import error:", err);
    }
    inputEl.value = "";
  };
  reader.onerror = () => {
    toast("❌ Could not read file", "var(--absent)");
    inputEl.value = "";
  };
  reader.readAsArrayBuffer(file);
}
